import React from "react"
import { Link as HeroUILink, cn } from "@heroui/react"
import { FaFacebook, FaGithub, FaLinkedin } from "react-icons/fa6"
import { Logo } from "@sb-components/atoms/display/Logo/Logo"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { IconComponent } from "@sb-components/atoms/buttons/Button/Button"
import { Container } from "@sb-components/frames/Container/Container"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { FooterLinkColumn } from "./FooterLinkColumn"

/**
 * BLOCK ΓÇö `Footer`: the marketing site footer. See the component's own file
 * header for the full port/reuse ledger; this story only exercises what a
 * caller actually configures.
 *
 * ONE LEAF ΓÇö the footer has a single structural shape (brand column, two link
 * columns, bottom bar); nothing about its composition ever drops or gains a
 * whole node. Longer vs. shorter link lists are DATA, so they live as states
 * inside this one leaf rather than separate leaves.
 */

/** One row inside a footer link column, or one of the two bottom-bar legal links. */
export interface FooterLinkItem {
    /** Stable id ΓÇö also the React key. */
    id: string
    /** Visible label, already localized by the caller. */
    label: string
    /** Fired when the row is pressed ΓÇö navigation is the caller's job. */
    onPress: () => void
}

/** One founder social icon link. */
export interface FooterSocialLink {
    /** Stable id ΓÇö also the React key. */
    id: string
    /** Aria-label for the glyph-only trigger, e.g. "GitHub". */
    label: string
    /** Brand glyph component (a `react-icons/fa6` icon ΓÇö see file header). */
    icon: IconComponent
    /** Fired when the icon is pressed ΓÇö opening the external URL is the caller's job. */
    onPress: () => void
}

/** Props for {@link Footer}. */
export interface FooterProps {
    /** The "Explore" column's rows (courses/blog/talents/jobs/community in the real app). */
    exploreLinks: Array<FooterLinkItem>
    /** The "Support" column's rows (contact/email in the real app). */
    supportLinks: Array<FooterLinkItem>
    /** Founder social links (Facebook/LinkedIn/GitHub in the real app). */
    socials: Array<FooterSocialLink>
    /** Fired when the bottom-bar "Terms" stub is pressed. */
    onTermsPress: () => void
    /** Fired when the bottom-bar "Privacy" stub is pressed. */
    onPrivacyPress: () => void
    /** Extra class on the root `<footer>` (placement only). */
    className?: string
}

/**
 * The marketing site footer. See the file header for the static-vs-prop copy
 * split and the BrandLockup/icon-rule judgement calls.
 *
 * @param props - {@link FooterProps}
 */
const Footer = ({
    exploreLinks,
    supportLinks,
    socials,
    onTermsPress,
    onPrivacyPress,
    className,
}: FooterProps) => {
    const year = new Date().getFullYear()

    const wordmark = (
        <>
            <div className="text-sm font-semibold leading-none text-foreground">StarCi</div>
            <div className="text-[8px] uppercase leading-none text-muted">Academy</div>
        </>
    )

    // brand mark + wordmark, inlined (see file header: BrandLockup not
    // promoted). `StackH`/`StackV` (not a hand-rolled flex span) per ┬º13z ΓÇö
    // spacing is words. `Logo` itself stays unbadged here, same as `Navbar`'s
    // own brand-mark span (not in either block's ANNOTATE map).
    const brandMark = (
        <>
            <Logo size="footer" />
            <div className="hidden @app-md:flex">
                <StackV gap={1} items={[() => wordmark]} />
            </div>
        </>
    )

    const socialLinks = socials.map((social) => {
        const Icon = social.icon
        return (
            <HeroUILink
                key={social.id}
                onPress={social.onPress}
                aria-label={social.label}
                className="text-muted transition-colors hover:text-foreground"

            >
                <Icon className="size-5" aria-hidden />
            </HeroUILink>
        )
    })

    const brandColumn = (
        <>
            <StackH gap={1} classNames={["w-fit", "self-start"]} items={[() => brandMark]} />
            <Typography
                size="sm"
                color="muted"
                text="Learn by building real systems with your own hands ΓÇö ready for any technical interview."

            />
            <StackH gap={3} items={[() => socialLinks]} />
        </>
    )

    const linkColumns = (
        <>
            <FooterLinkColumn title="Explore" links={exploreLinks} />
            <FooterLinkColumn title="Support" links={supportLinks} />
        </>
    )

    // top region: brand + tagline + socials (left) ┬╖ two link columns (right)
    const topRegion = (
        <>
            <div className="max-w-sm">
                <StackV gap={4} items={[() => brandColumn]} />
            </div>
            <StackH gap={7} principle="layout-split"
                explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                at="sm" items={[() => linkColumns]}  />
        </>
    )

    const legalLinks = (
        <>
            <HeroUILink
                onPress={onTermsPress}
                className="cursor-pointer text-xs text-muted transition-colors hover:text-foreground"

            >
                Terms
            </HeroUILink>
            <HeroUILink
                onPress={onPrivacyPress}
                className="cursor-pointer text-xs text-muted transition-colors hover:text-foreground"

            >
                Privacy
            </HeroUILink>
        </>
    )

    // bottom bar: copyright + credit (left) ┬╖ legal stubs (right)
    const bottomBar = (
        <>
            <Typography
                size="xs"
                color="muted"
                text={`┬⌐ ${year} StarCi Academy ┬╖ Built by Nguyß╗àn V─ân Tß╗▒ C╞░ß╗¥ng`} // vn-ok: the author's real name

            />
            <StackH gap={3} items={[() => legalLinks]} />
        </>
    )

    const sections = (
        <>
            <StackH
                gap={7}
                principle="layout-split"
                explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                justify="between"
                at="md"

                items={[() => topRegion]}
            />
            <div className="items-start @app-sm:items-center">
                <StackH
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                    justify="between"
                    at="sm"

                    items={[() => bottomBar]}
                />
            </div>
        </>
    )

    const footerBody = (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
            divider items={[() => sections]}  />
    )

    return (
        <footer className={cn("border-t border-default bg-surface", className)}>
            <Container size="xl" padding={6} body={() => footerBody} />
        </footer>
    )
}

export { Footer }

/** Re-exported so `FaFacebook`/`FaLinkedin`/`FaGithub` fixtures stay ONE source for stories. */
export { FaFacebook, FaGithub, FaLinkedin }

import React from "react"
import type { ReactNode } from "react"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { Spinner } from "@sb-components/atoms/display/Spinner/Spinner"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnrollGate, type EnrollGateProps } from "@sb-components/starci/blocks/learn/EnrollGate/EnrollGate"
import { ContentAiFab } from "@sb-components/starci/blocks/learn/ContentAiFab/ContentAiFab"
import {
    ContentAiSelectionAsk,
    type ContentAiSelectionAskAnchor,
} from "@sb-components/starci/blocks/learn/ContentAiSelectionAsk/ContentAiSelectionAsk"

/**
 * `LearnShell` ΓÇö the wrapper mounted once per `/learn/**` scope. Five
 * structural leaves, each gaining or losing a whole node:
 *   - `RailSurface`        ΓÇö rail mounted beside `children`, one floating FAB.
 *   - `NoRailSurface`      ΓÇö no rail; `children` fills the width.
 *   - `SelectionAskActive` ΓÇö gains the `ContentAiSelectionAsk` pill alongside
 *     the FAB.
 *   - `AiSuppressed`       ΓÇö `isAssessmentLive` loses both AI trigger nodes.
 *   - `EnrollGated`        ΓÇö the whole rail+children row is replaced by
 *     `EnrollGate`.
 */

/** Which `/learn/**` surface is currently active ΓÇö drives whether a rail mounts. */
export type LearnSurface = "content" | "personalProject" | "leaderboard" | "other"

/** Surfaces whose real rail body (out of scope here, see file header) exists in the real app. */
const RAIL_SURFACES: ReadonlySet<LearnSurface> = new Set(["content", "leaderboard"])

/** Rail persistence + bounds ΓÇö mirrors the real `learn/layout.tsx` rail's own defaults. */
const RAIL_STORAGE_KEY = "learn-shell-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 256
const RAIL_MAX_WIDTH = 480
const RAIL_ARIA_LABEL = "Drag to resize the side panel"
const RAIL_LOADING_LABEL = "Loading side panel"

/**
 * Fields `LearnShell` relays into `EnrollGate` ΓÇö see the file header's
 * "`preview` IS A RELAYED SLOT" note for why `preview`/`price` ride along with
 * `title`/`description`, plus the `onEnroll` callback the gate needs to fire.
 */
export interface LearnShellEnrollGateProps
    extends Pick<EnrollGateProps, "title" | "description" | "preview" | "price"> {
    /** Fired when the learner takes the gate's enroll CTA. */
    onEnroll: () => void
}

/**
 * A resolved, already-positioned "ask AI about this selection" request ΓÇö see
 * the file header for why `LearnShell` never tracks the selection itself.
 */
export interface LearnShellSelectionAsk {
    /** Viewport point to plant the pill at (already resolved by the caller). */
    anchor: ContentAiSelectionAskAnchor
    /** `true` ΓåÆ the pill carries the "New" badge. */
    isNew?: boolean
}

/** Props for {@link LearnShell}. */
export interface LearnShellProps {
    /** Which `/learn/**` surface is mounted right now ΓÇö drives which rail body would mount. */
    activeSurface: LearnSurface
    /** `true` ΓåÆ the active surface requires enrollment the viewer does not have; replaces the whole body with `EnrollGate`. */
    isEnrollGated: boolean
    /** `true` ΓåÆ a timed/live assessment is running; suppresses BOTH AI triggers regardless of `isEnrollGated`. */
    isAssessmentLive: boolean
    /** `title`/`description`/`preview`/`price` relayed into `EnrollGate`, plus its `onEnroll`. Required only while `isEnrollGated`. */
    enrollGateProps?: LearnShellEnrollGateProps
    /** Fired when the floating AI trigger is pressed ΓÇö the real layout opens the AI chat rail/drawer in response. */
    onOpenAiChat: () => void
    /** `true` ΓåÆ that chat surface is already open, so `ContentAiFab` hides instead of floating on top of it. */
    isAiChatOpen?: boolean
    /** The current text-selection ask request, already resolved+positioned by the caller. `null`/omitted ΓåÆ no selection to react to. */
    selectionAsk?: LearnShellSelectionAsk | null
    /** Fired when the selection-ask pill is pressed. */
    onOpenSelectionAsk: () => void
    /** The active route's own content ΓÇö the one place `ReactNode` is valid above frame tier (┬º12). */
    children: ReactNode
}

/**
 * The `/learn/**` layout shell. See the file header for the full contract, the
 * scope gaps left deliberately open, and why `LeaderboardCategoryNav` was not
 * reused despite the inventory hint.
 *
 * @param props - {@link LearnShellProps}
 */
const LearnShell = ({
    activeSurface,
    isEnrollGated,
    isAssessmentLive,
    enrollGateProps,
    onOpenAiChat,
    isAiChatOpen = false,
    selectionAsk = null,
    onOpenSelectionAsk,
    children,
}: LearnShellProps) => {
    // A locked surface has nothing real to ask AI about yet, on top of the
    // brief's own `isAssessmentLive` suppression.
    const showAiTriggers = !isEnrollGated && !isAssessmentLive

    const railAndContent = [
        ...(RAIL_SURFACES.has(activeSurface) ? [() => (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={RAIL_ARIA_LABEL}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <StackV
                    gap={1}
                    principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                    align="center"
                    justify="center"
                    classNames={["h-full"]}

                    items={[() => <Spinner label={RAIL_LOADING_LABEL} />]}
                />
            </ResizableRail>
        )] : []),
        () => (
            <div className="min-w-0 flex-1">
                {children}
            </div>
        ),
    ]

    return (
        <div>
            {isEnrollGated && enrollGateProps != null ? (
                <EnrollGate
                    title={enrollGateProps.title}
                    description={enrollGateProps.description}
                    preview={enrollGateProps.preview}
                    price={enrollGateProps.price}
                    onEnroll={enrollGateProps.onEnroll}


                />
            ) : (
                <div className="min-h-[calc(100dvh-4rem)]">
                    <StackH
                        gap={1}
                        items={railAndContent}
                    />
                </div>
            )}

            {showAiTriggers ? (
                <>
                    <ContentAiFab
                        onOpen={onOpenAiChat}
                        isOpen={isAiChatOpen}


                    />
                    {selectionAsk != null ? (
                        <ContentAiSelectionAsk
                            onOpen={onOpenSelectionAsk}
                            anchor={selectionAsk.anchor}
                            isNew={selectionAsk.isNew}


                        />
                    ) : null}
                </>
            ) : null}
        </div>
    )
}

export { LearnShell }

"use client"

import React, { type ComponentType } from "react"
import Link from "next/link"
import { cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"
import { type VerdictBand, verdictBandClassName } from "../verdict-band"

/**
 * The interactive anchor for a clickable surface-list row. An INTERNAL app route
 * (href starting with `/`) renders a Next `<Link>` ΓåÆ client-side `router.push`:
 * SPA navigation that keeps history (Back works) with NO full-page reload ΓÇö and
 * NEVER `router.replace` (a link click must not erase the entry it came from).
 * Protocol / external hrefs (`mailto:`, `tel:`, `http(s)://`, `#`) fall back to a
 * native `<a>` (Next `<Link>` is for in-app routes only). Ref feedback 2026-07-17
 * "clicking a row = router.push, not router.replace, even if it's a link".
 *
 * Shared by {@link SurfaceListCardRow} and {@link SurfaceListCardItem} ΓÇö each hands
 * in its own `dataComponent` so the rendered anchor still carries that caller's own
 * identity rather than a generic one.
 */
const RowAnchor = ({
    href,
    onClick,
    className,
    dataComponent,
    children,
}: {
    href: string
    onClick?: () => void
    className?: string
    dataComponent: string
    children: React.ReactNode
}) => {
    if (href.startsWith("/")) {
        return (
            <Link href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
                {children}
            </Link>
        )
    }
    return (
        <a href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
            {children}
        </a>
    )
}

/** Props for {@link SurfaceListCard}. */
export interface SurfaceListCardProps extends WithClassNames<undefined> {
    /** The rows ({@link SurfaceListCardRow}) of the joined list. */
    children: React.ReactNode
    /**
     * Renders `border border-default` instead of `shadow-surface` ΓÇö for when
     * this list sits NESTED inside another surface (a modal/drawer body),
     * where `--surface-shadow` can render invisible against the parent surface
     * (dark mode) ΓÇö nested cards need a border to delineate (`components/card.md`
     * ┬º"surface-in-surface / nested" ΓÇö KEEP border, do NOT convert to shadow).
     * Defaults to `false` (existing top-level usages keep the shadow look).
     */
    bordered?: boolean
    /**
     * Set when a sentence-tier component roots on this card: it then emits THAT
     * component's identity instead of its own, so the caller never wraps itself in an
     * identity div (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * Bounded SURFACE list card: one `bg-surface` container with a border + large
 * radius, holding {@link SurfaceListCardRow}s edge-to-edge (the `Accordion
 * variant="surface"` skin ΓÇö NOT a real accordion). Each row owns the FULL-BLEED
 * separator + hover; the last row hides its separator automatically (reviewer,
 * 2026-07-14: "surface-in-surface gets a full-width separator too") ΓÇö full-bleed
 * everywhere, no inset-vs-nested split).
 *
 * Use for a list of clickable items that should read as ONE card (foundation
 * categories/resources, payment methodsΓÇª), not N separate cards. Style lives
 * here (block); features only feed rows. Ref `elements/card.md` ┬º3c.
 *
 * REUSE NOTE: `composites/cards/SurfaceCard`'s `.List` member is the newer,
 * DATA-driven (`items`) sibling of this exact shape (its own header even says
 * "was `SurfaceListCard` + its two rows"). This folder keeps the original
 * children-based API on purpose ΓÇö ~90 call sites across the app compose it with
 * JSX rows today, and moving them to `items` is a call-site migration outside
 * this pass's scope, not a rewrite this file can make alone.
 *
 * @param props - {@link SurfaceListCardProps}
 * @see Story: .storybook/stories/blocks/cards/SurfaceListCard/SurfaceListCard.stories
 */
export const SurfaceListCard = ({ children, bordered = false, className, identity }: SurfaceListCardProps) => (
    <div
        className={cn(
            "overflow-hidden rounded-3xl bg-surface",
            bordered ? "border border-default" : "shadow-surface",
            className,
        )}
        {...resolveIdentity(identity, { tier: "composite", name: "SurfaceListCard" })}
    >
        {children}
    </div>
)

/** Props for {@link SurfaceListCardRow}. */
export interface SurfaceListCardRowProps extends WithClassNames<undefined> {
    /** Optional leading slot (thumbnail/icon), kept at intrinsic size ΓÇö a buildable slot. */
    leading?: ComponentType
    /** Primary line ΓÇö medium foreground, single-line truncate. */
    title: string
    /**
     * Extra className applied directly to a wrapper around the title's own
     * `Typography` element (e.g. `text-accent-soft-foreground` for a selected row) ΓÇö
     * a raw string, not the closed `classNames` union, because it carries arbitrary
     * one-off colour overrides no fixed vocabulary can enumerate (mirrors
     * `SurfaceCardListItem.titleClassName`, the same escape hatch on the newer
     * sibling shape). `text-decoration-color` for `hover="underline"` is resolved
     * from `Typography`'s own `underlineOnGroupHover`, which reads the SAME
     * element's `color` ΓÇö not a nested child's ΓÇö so the hover underline never
     * mismatches the text colour. Ref `components/icon.md` ┬º6.
     */
    titleClassName?: string
    /** Optional secondary line ΓÇö muted, smaller, single-line truncate. */
    subtitle?: string
    /** Optional right-aligned metadata slot (chips/counts) before the trailing slot ΓÇö a buildable slot. */
    meta?: ComponentType
    /** Optional far-right slot (caret / inline action) ΓÇö a buildable slot. */
    trailing?: ComponentType
    /** Press handler ΓåÆ renders an interactive `<button>` row. */
    onPress?: () => void
    /** Link target ΓåÆ renders an `<a>` row that navigates on click. */
    href?: string
    /** Tints the row as the active selection. */
    selected?: boolean
    /** Disables the row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment. `"fill"` (default) tints the whole row (`bg-default`) ΓÇö for
     * card-like rows / bounded objects. `"underline"` is link-style: the TITLE
     * underlines on hover with NO row fill ΓÇö for a list whose title IS the link
     * (e.g. a most-read list). Ref `interactive-needs-hover` (row-as-link ΓåÆ underline
     * the label, don't colour the whole block).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict band: an inset colored PILL on the left marking this row with a signal
     * that comes from DATA (`card.md` ┬º3i) ΓÇö e.g. a keyword's popularity tier. See
     * {@link VerdictBand} (same shape as `SurfaceListCardItem.withVerdict`).
     */
    withVerdict?: VerdictBand
}

/**
 * One row of a {@link SurfaceListCard}, laying out leading ┬╖ title+subtitle ┬╖
 * meta+trailing (the same slot shape as `ListRow`, surface-card skin) with a
 * full-bleed inset separator auto-hidden on the last row. STATIC by default (a
 * plain `<div>`, NO hover/focus/cursor); pass `onPress`/`href` to make the whole
 * row a tappable `<button>`/`<a>` with `hover:bg-default` + focus ring. A static
 * row never fakes interactivity with a hover tint (`hover-style-matches-clickable-nature`).
 *
 * The row's OWN frame (separator, hover fill, focus ring, verdict band) is a shape
 * decision this composite owns directly (`cn`) ΓÇö no frame carries an `after:`
 * pseudo-element separator or a data-driven inset shadow. The row's INTERIOR ΓÇö
 * leading ┬╖ title/subtitle ┬╖ meta/trailing ΓÇö is assembled from `Typography` inside
 * `Box`/`StackH` frames wherever a frame can express it exactly (title/subtitle
 * keeps a literal `gap-0` column, one step tighter than `Stack`'s narrowest `gap={1}`
 * step, so it stays a plain flex column).
 *
 * @param props - {@link SurfaceListCardRowProps}
 */
export const SurfaceListCardRow = ({
    leading: Leading,
    title,
    titleClassName,
    subtitle,
    meta: Meta,
    trailing: Trailing,
    onPress,
    href,
    selected = false,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
}: SurfaceListCardRowProps) => {
    // a row is only interactive when it actually does something; a STATIC row must
    // not fake interactivity with a hover tint / focus ring / button semantics
    // (`hover-style-matches-clickable-nature` ΓÇö mirrors SurfaceListCardItem).
    const interactive = Boolean(onPress || href)
    const underlineHover = hover === "underline"
    const rowClassName = cn(
        "relative flex w-full items-center gap-3 p-3 text-left",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        // hover + focus + cursor ONLY when interactive. link-style rows form a hover
        // `group` (the title underlines) with no fill; card-style rows tint the row
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        interactive && (underlineHover ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        "disabled:cursor-not-allowed disabled:opacity-60",
        selected && "bg-accent-soft",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        className,
    )

    const content = (
        <>
            {Leading ? <div className="shrink-0"><Leading /></div> : null}
            {/* Deliberately NOT `StackV`: the closest step on the frame's gap scale is
                `gap={1}` (0.25rem) and this column needs a true `gap-0` ΓÇö the two text
                lines are meant to sit with no seam between them (missing vocabulary: the
                frame has no zero step, see `_spacing.ts` `AllowedGap`). */}
            <div className="flex min-w-0 flex-col gap-0">
                <div className={titleClassName}>
                    <Typography size="sm" truncate underlineOnGroupHover={underlineHover} text={title} />
                </div>
                {subtitle ? <Typography size="xs" color="muted" truncate text={subtitle} /> : null}
            </div>
            {Meta || Trailing ? (
                <Box principle="push-end" className="ml-auto shrink-0"
                    explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                    <StackH gap={2} items={[() => (Meta ? <Meta /> : null), () => (Trailing ? <Trailing /> : null)]} />
                </Box>
            ) : null}
        </>
    )

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={rowClassName} dataComponent="SurfaceListCardRow">
                {content}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={rowClassName}
                data-tier="composite"
                data-component="SurfaceListCardRow"
            >
                {content}
            </button>
        )
    }
    // static row (no onPress/href) ΓÇö a plain div: no button semantics, no hover
    return (
        <div className={rowClassName} data-tier="composite" data-component="SurfaceListCardRow">
            {content}
        </div>
    )
}

/** Props for {@link SurfaceListCardItem}. */
export interface SurfaceListCardItemProps extends WithClassNames<undefined> {
    /** Arbitrary row content (the block owns padding + the inset separator). */
    children: React.ReactNode
    /** Press handler ΓåÆ renders an interactive `<button>` row (hover + focus ring). */
    onPress?: () => void
    /** Link target ΓåÆ renders an `<a>` row that navigates on click. */
    href?: string
    /** Disables the interactive row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment for an interactive row. `"fill"` (default) tints the whole
     * row (`bg-default`) ΓÇö the accordion-skin hover, for SELECT/expand rows that
     * keep you on the surface (e.g. payment methods). `"underline"` makes the row a
     * hover `group` with NO fill ΓÇö for a NAV row whose title is a link (navigates
     * away); the feature adds `group-hover:underline` to its title. Ref
     * `hover-style-matches-clickable-nature` (go-there ΓåÆ underline, stay-here ΓåÆ fill).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict variant: a LEFT band (`border-l-4`) marking this row with a signal that
     * comes from DATA (`card.md` ┬º3i) ΓÇö e.g. the league's promote/demote zone. See
     * {@link VerdictBand} (same shape as `SectionCard.withVerdict`).
     */
    withVerdict?: VerdictBand
}

/**
 * One free-form row of a {@link SurfaceListCard} ΓÇö bespoke content (not the fixed
 * leading/title/subtitle slots of {@link SurfaceListCardRow}). The block owns the
 * row padding + inset bottom separator (auto-hidden on the last row); the feature
 * lays out whatever it needs inside (e.g. a changelog entry, or a course row with a
 * progress bar). STATIC by default; pass `onPress`/`href` to make the WHOLE row a
 * tappable `<button>`/`<a>`. `hover="fill"` (default) tints the row (accordion skin);
 * `hover="underline"` is link-style (the row is a `group`, no fill ΓÇö the feature
 * underlines its own title). Ref `elements/card.md` ┬º3b/┬º3c.
 *
 * @param props - {@link SurfaceListCardItemProps}
 */
export const SurfaceListCardItem = ({
    children,
    onPress,
    href,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
}: SurfaceListCardItemProps) => {
    const interactive = Boolean(onPress || href)
    const itemClassName = cn(
        "relative block w-full p-3 text-left",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        // link-style rows form a hover `group` (the title underlines) with NO fill;
        // select/expand rows tint the whole row (accordion skin)
        interactive && (hover === "underline" ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={itemClassName} dataComponent="SurfaceListCardItem">
                {children}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={itemClassName}
                data-tier="composite"
                data-component="SurfaceListCardItem"
            >
                {children}
            </button>
        )
    }
    return (
        <div className={itemClassName} data-tier="composite" data-component="SurfaceListCardItem">
            {children}
        </div>
    )
}

