"use client"

import React, {
    type Key,
    type ReactNode,
} from "react"
import {
    ListBox,
    Select,
    Tabs,
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import {
    ExtendedTabs,
} from "../ExtendedTabs"

/** One tab in a {@link TabsCardGroup}. */
export interface TabsCardItem {
    /** Stable id used as the selection key. */
    key: string
    /** Tab content (text, or an icon + text row). */
    label: ReactNode
    /** Optional leading icon rendered before the label. */
    icon?: ReactNode
    /** Render the tab but block selection. */
    isDisabled?: boolean
    /** Render muted ΓÇö for a locked/premium tab that is still clickable (the parent
     * intercepts the selection, e.g. to open a paywall). */
    muted?: boolean
}

/** A controlled group of secondary tabs ΓÇö one side of a {@link TabsCard}. */
export interface TabsCardGroup {
    /** Tabs in display order. */
    items: Array<TabsCardItem>
    /** Currently selected tab key. */
    selectedKey: string
    /** Accessible name for this group's tab list. */
    ariaLabel: string
    /** Fired with the newly selected tab key. */
    onSelectionChange: (key: Key) => void
}

/** Props for the {@link TabsCard} block. */
export interface TabsCardProps extends WithClassNames<undefined> {
    /** Primary tab group, pinned left. */
    leftTabs: TabsCardGroup
    /**
     * Inline cluster rendered right AFTER the left tab group ΓÇö actions that belong
     * to the left axis (e.g. a manage-menu for the active tab, an "+" add button,
     * an overflow count). Rendered as SIBLINGS of the tab list, never inside a
     * `Tabs.Tab` (react-aria tabs can't nest interactive elements).
     */
    leftEnd?: ReactNode
    /** Optional secondary tab group, pinned right (e.g. a language switcher). */
    rightTabs?: TabsCardGroup
    /**
     * Collapse `rightTabs` into a compact dropdown below `sm` (mobile), expanding
     * back to inline tabs from `sm` up. Use when the right group is a set-once
     * preference (e.g. the language switcher) that would crowd a narrow reading
     * column. Defaults to inline at every width.
     */
    collapseRightOnMobile?: boolean
    /**
     * Render `rightTabs` with NEUTRAL selected chrome (foreground underline) instead
     * of accent. Use when the right group is a "same content, different presentation"
     * toggle (e.g. the language switcher) ΓÇö only the primary `leftTabs` group should
     * carry the accent, so the toolbar has one accent signal, not two. Defaults to
     * accent (both groups accent).
     */
    rightTabsNeutral?: boolean
    /**
     * `"secondary"` (default) = in-page content tabs ΓÇö underline, hugs its own
     * label width, no outer baseline (this component's caller owns full-width
     * chrome if it wants any, ┬º1). `"primary"` = page-FEATURE tabs that switch
     * the ENTIRE panel content ΓÇö full-width, evenly-stretched segmented pill
     * (HeroUI's own default Tabs look). Use `"primary"` for top-level section
     * switches (e.g. Start/History/Statistics), `"secondary"` for a content
     * filter/language-switcher. Applies to BOTH groups (a toolbar is either
     * page-feature nav or in-page filter nav, not a mix).
     */
    variant?: "primary" | "secondary"
    /**
     * `"md"` (default) = full-width `"primary"` tabs (unchanged). `"sm"`
     * shrinks BOTH groups to a compact `w-fit` strip with smaller
     * padding/text ΓÇö for a `"primary"` choice that's a secondary/nested
     * setting, not a top-level page switch (e.g. a toggle inside a modal
     * panel). No effect on `"secondary"` (already hug-content).
     */
    size?: "sm" | "md"
}

/** size ΓåÆ extra Tab className override (md = HeroUI's own default, no override). */
const TAB_SIZE_SM = "h-auto! w-auto! px-3! py-2! text-xs!"

/**
 * Selected-state TEXT color only (accent tab group) ΓÇö the underline itself now
 * comes from `<Tabs.Indicator/>` (native HeroUI `.tabs--secondary` accent bar).
 * Corrected 2026-07-09: this used to ALSO draw its own manual `border-b-2
 * border-accent`, which ΓÇö once `<Tabs.Indicator/>` was added per tabs.md ┬º5 ΓÇö
 * doubled up with the indicator's own bottom line under the same tab.
 */
const TAB_CLASS_ACCENT = "rounded-none data-[selected=true]:text-accent-soft-foreground"

/**
 * Selected-state chrome ΓÇö NEUTRAL foreground underline (secondary toggle
 * group, no accent). Kept on the MANUAL `border-b-2` technique (unlike
 * `TAB_CLASS_ACCENT` above) because `.tabs--secondary`'s indicator is
 * hardcoded `bg-accent` ΓÇö there is no "neutral-colored" native indicator to
 * switch to, so `<Tabs.Indicator/>` is suppressed for this path (see below).
 */
const TAB_CLASS_NEUTRAL =
    "rounded-none data-[selected=true]:border-b-2 data-[selected=true]:border-foreground data-[selected=true]:font-medium data-[selected=true]:text-foreground"

/**
 * Two secondary (underline) tab groups sharing one toolbar row: `leftTabs` pinned
 * left, optional `rightTabs` pinned right, a `gap-3` gutter between them. Both sides
 * use the same secondary chrome (no primary), so the row reads as one nav layer ΓÇö
 * e.g. content tabs on the left and a language switcher on the right. Pass each side
 * as data (items + selectedKey + onSelectionChange); the block owns all styling.
 *
 * @param props - {@link TabsCardProps}
 * @see Story: .storybook/stories/blocks/navigation/TabsCard/TabsCard.stories
 */
export const TabsCard = ({
    leftTabs,
    leftEnd,
    rightTabs,
    collapseRightOnMobile,
    rightTabsNeutral,
    variant = "secondary",
    size = "md",
    className,
}: TabsCardProps) => {
    /** Render one controlled tab group (`accent` = accent selected chrome, secondary-only). */
    const renderGroup = (group: TabsCardGroup, accent = true): ReactNode => (
        <ExtendedTabs
            variant={variant}
            size={size}
            selectedKey={group.selectedKey}
            onSelectionChange={group.onSelectionChange}
        >
            <Tabs.ListContainer>
                <Tabs.List aria-label={group.ariaLabel}>
                    {group.items.map((item) => (
                        <Tabs.Tab
                            key={item.key}
                            id={item.key}
                            isDisabled={item.isDisabled}
                            className={cn(
                                variant === "secondary" && (accent ? TAB_CLASS_ACCENT : TAB_CLASS_NEUTRAL),
                                size === "sm" && TAB_SIZE_SM,
                                item.muted && "text-muted",
                            )}
                        >
                            <span className="flex items-center gap-2">
                                {item.icon}
                                {/* a tab WITH an icon hides its label visually on mobile
                                    (icon-only) and shows it from sm up; `sr-only` keeps the
                                    accessible name on mobile. An icon-less tab always shows it. */}
                                {item.label ? (
                                    <span className={cn(item.icon && "sr-only @app-sm:not-sr-only")}>
                                        {item.label}
                                    </span>
                                ) : null}
                            </span>
                            {/* REQUIRED for "primary" and secondary-ACCENT (fe/components/tabs.md
                                ┬º5) ΓÇö HeroUI Tabs renders no selected-state chrome of its own;
                                without this, "primary" reads as plain undifferentiated text (no
                                floating pill) and secondary-accent has no underline at all.
                                Suppressed for secondary-NEUTRAL: `.tabs--secondary`'s indicator is
                                hardcoded `bg-accent` (no neutral color option), so that path keeps
                                its OWN `border-b-2 border-foreground` (TAB_CLASS_NEUTRAL) as the
                                sole indicator instead of doubling up with a wrong-colored one. */}
                            {(variant === "primary" || accent) && <Tabs.Indicator />}
                        </Tabs.Tab>
                    ))}
                </Tabs.List>
            </Tabs.ListContainer>
            {/* react-aria's useTab ALWAYS computes an `aria-controls` id pointing at
                a tabpanel with this tab's key, whether or not one is ever rendered
                (no console warning fires ΓÇö see fe review 2026-07-14). Without this,
                the selected tab's `aria-controls` dangles at a non-existent element,
                an axe-core/Lighthouse-flagged a11y bug. `TabsCard` never shows panel
                CONTENT here (callers render their own content elsewhere), so these
                panels stay empty/`sr-only` ΓÇö they exist purely to satisfy the
                tabΓåötabpanel ARIA relationship. */}
            {group.items.map((item) => (
                <Tabs.Panel key={item.key} id={item.key} className="sr-only">{null}</Tabs.Panel>
            ))}
        </ExtendedTabs>
    )

    /**
     * Render `group` as a compact single-select dropdown ΓÇö the mobile form of a
     * set-once right group (e.g. the language switcher) so it never crowds the row.
     */
    const renderSelect = (group: TabsCardGroup): ReactNode => {
        const selected = group.items.find((item) => item.key === group.selectedKey)
        return (
            <Select.Root<{ id: string }, "single">
                variant="secondary"
                aria-label={group.ariaLabel}
                selectedKey={group.selectedKey}
                onSelectionChange={(key) => {
                    if (key !== null) {
                        group.onSelectionChange(key)
                    }
                }}
            >
                <Select.Trigger aria-label={group.ariaLabel}>
                    <Select.Value>
                        {() => (
                            <span className="flex items-center">
                                {selected?.icon}
                                {/* trigger is icon-only to stay compact; keep the
                                    selected option's name for screen readers */}
                                <span className="sr-only">{selected?.label}</span>
                            </span>
                        )}
                    </Select.Value>
                    <Select.Indicator />
                </Select.Trigger>
                <Select.Popover>
                    <ListBox.Root aria-label={group.ariaLabel}>
                        {group.items.map((item) => (
                            <ListBox.Item
                                key={item.key}
                                id={item.key}
                                isDisabled={item.isDisabled}
                                textValue={
                                    typeof item.label === "string" ? item.label : item.key
                                }
                            >
                                <span className="flex items-center gap-2">
                                    {item.icon}
                                    {item.label}
                                </span>
                            </ListBox.Item>
                        ))}
                    </ListBox.Root>
                </Select.Popover>
            </Select.Root>
        )
    }

    return (
        <div className={cn("flex items-center justify-between gap-3", className)}>
            {leftEnd ? (
                <div className="flex min-w-0 items-center gap-1">
                    {renderGroup(leftTabs)}
                    {leftEnd}
                </div>
            ) : renderGroup(leftTabs)}
            {rightTabs
                ? collapseRightOnMobile
                    ? (
                        <>
                            {/* mobile: collapse to a dropdown; sm+: inline tabs */}
                            <div className="@app-sm:hidden">{renderSelect(rightTabs)}</div>
                            <div className="hidden @app-sm:block">{renderGroup(rightTabs, !rightTabsNeutral)}</div>
                        </>
                    )
                    : renderGroup(rightTabs, !rightTabsNeutral)
                : null}
        </div>
    )
}

"use client"

import React from "react"
import { CodePreviewTabs } from "../CodePreviewTabs"

/**
 * One pane inside a `:::tab` block: the source code (`:::code` ΓåÆ ` ```tsx ` Shiki) or the live
 * demo (`:::preview` ΓåÆ ` ```mdx ` render). It only renders its children (the fence rendered by the
 * normal `pre` handler); {@link TabsBlock} identifies which pane is which by the original directive
 * tag name (`tabcode`/`tabpreview`), not by this prop.
 */
export const TabPane = (
    { children }: { kind: "code" | "preview", children?: React.ReactNode },
) => <>{children}</>

/** The hast node react-markdown threads onto every element renderer via the `node` prop. */
interface NodeProp {
    node?: { tagName?: string }
}

/**
 * Renders a `:::tab` block as **[ Preview | Code ]** tabs via the shared {@link CodePreviewTabs}.
 *
 * Use this (not a single ` ```mdx `) when the real code has logic/imports that can't be evaluated:
 * the `:::code` pane shows the FULL code (Shiki, not rendered) and the `:::preview` pane shows a
 * separate renderable demo.
 *
 * Panes are matched by the original directive tag name carried on each child's `node` prop
 * (`tabcode` / `tabpreview`) ΓÇö order-independent. NOTE: the children TabsBlock receives are the
 * `tabcode`/`tabpreview` element renderers themselves, whose own props are only `{ node, children }`;
 * the `kind` lives on the `TabPane` they *return*, so it is NOT visible here ΓÇö match on `node.tagName`.
 * @param props.children - The `:::code` / `:::preview` pane elements.
 */
export const TabsBlock = ({ children }: { children?: React.ReactNode }) => {
    let previewNode: React.ReactNode = null
    let codeNode: React.ReactNode = null
    React.Children.forEach(children, (child) => {
        if (!React.isValidElement(child)) {
            return
        }
        const tagName = (child.props as NodeProp).node?.tagName
        if (tagName === "tabpreview") {
            previewNode = child
        } else if (tagName === "tabcode") {
            codeNode = child
        }
    })

    if (previewNode == null && codeNode == null) {
        return <>{children}</>
    }
    return <CodePreviewTabs preview={previewNode} code={codeNode} />
}

import React from "react"
import type { Components } from "react-markdown"
import { isInlineCode } from "react-shiki"
import * as HeroUI from "@heroui/react"
import { CaretDownIcon } from "@phosphor-icons/react"
import {
    MarkdownTable,
    MarkdownTableBody,
    MarkdownTableColumn,
    MarkdownTableHead,
    MarkdownTableRow,
} from "./MarkdownTableParts"
import { CodeToHtml } from "./CodeToHtml"
import { LayoutWidget } from "./LayoutWidget"
import { MermaidDiagram } from "./MermaidDiagram"
import { RenderReactComponent } from "./RenderReactComponent"
import { TabsBlock, TabPane } from "./TabsBlock"
import { Link as IntlLink } from "@/i18n/navigation"
import type { MarkdownRenderersParams } from "./types"

// Named handles used by the markdown element renderers below.
const { Link, Table } = HeroUI

// Tailwind size class per the old HeroUI `Text` `size` token. HeroUI v3.0.5 renamed
// `Text` ΓåÆ `Typography` and its root no longer accepts `size`/`elementType`, so prose
// blocks render through this tiny local helper instead ΓÇö keeping visuals pixel-identical
// and decoupled from the renamed component.
const PROSE_SIZE: Record<string, string> = {
    xs: "text-xs",
    sm: "text-sm",
    base: "text-base",
    lg: "text-lg",
    xl: "text-xl",
    "2xl": "text-2xl",
}

/**
 * Minimal prose text node: renders `elementType` with a size class plus extra classes.
 * Drop-in for the former HeroUI `<Text elementType size className>` used by the markdown
 * heading/paragraph/list renderers.
 * @param props.elementType - HTML element/tag to render (default `div`).
 * @param props.size - Size token mapped to a Tailwind text-size class (default `sm`).
 * @param props.className - Extra classes appended after the size class.
 * @param props.children - Inline content.
 */
const ProseText = ({
    elementType: As = "div",
    size = "sm",
    className,
    children,
}: {
    elementType?: React.ElementType
    size?: keyof typeof PROSE_SIZE
    className?: string
    children?: React.ReactNode
}) => React.createElement(
    As,
    { className: [PROSE_SIZE[size], className].filter(Boolean).join(" ") },
    children,
)

/**
 * Recursively flattens a React children tree to its plain-text content ΓÇö used to
 * derive a stable heading slug (and the "on this page" outline label) from the
 * rendered heading nodes.
 * @param node - The React node to read text from.
 * @returns The concatenated text content.
 */
const getNodeText = (node: React.ReactNode): string => {
    if (node === null || node === undefined || typeof node === "boolean") {
        return ""
    }
    if (typeof node === "string" || typeof node === "number") {
        return String(node)
    }
    if (Array.isArray(node)) {
        return node.map(getNodeText).join("")
    }
    if (React.isValidElement(node)) {
        return getNodeText((node.props as { children?: React.ReactNode }).children)
    }
    return ""
}

/**
 * Slugify heading text into a URL-safe anchor id (diacritics stripped, Vietnamese
 * Vietnamese d-with-stroke folded to `d`, non-alphanumerics collapsed to single hyphens). Deterministic so the
 * rendered heading id and any "on this page" outline reading it from the DOM agree.
 * @param text - The raw heading text.
 * @returns The anchor slug.
 */
const slugify = (text: string): string =>
    text
        .normalize("NFKD")
        .replace(/[╠Ç-═»]/g, "")
        .replace(/[─æ─É]/g, "d") // vn-ok: slug transliteration of the VI letter
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")

/**
 * Heading renderer factory: renders a section heading carrying a slug `id` +
 * `data-toc` markers so an "on this page" rail can scan the rendered article
 * (`#lesson-article [data-toc]`) and anchor-scroll to it. `scroll-mt-20` clears
 * the sticky navbar when jumped to.
 * @param level - The heading depth surfaced in the outline (2 or 3).
 * @param sizeClass - The prose size class keeping the visual identical to {@link ProseText}.
 */
const buildTocHeading = (level: 2 | 3 | 4, sizeClass: string, marginClass: string, anchorLabel: string) =>
    ({ children }: { children?: React.ReactNode }) => {
        // real heading tag (not a div) so the body keeps semantic outline for SEO
        const Tag = `h${level}` as "h2" | "h3" | "h4"
        const text = getNodeText(children)
        const id = slugify(text)
        return (
            <Tag
                id={id}
                data-toc=""
                data-toc-level={level}
                // clean label for the "on this page" rail ΓÇö read instead of textContent so the
                // hover anchor (#) and any inline code in the heading never leak into the outline.
                data-toc-label={text}
                className={`group ${marginClass} ${sizeClass} scroll-mt-20 font-semibold`.trim()}
            >
                {children}
                {/* Hover anchor (#) ΓÇö copy/share a deep link to the section (reading only). */}
                {anchorLabel ? (
                    <a
                        href={`#${id}`}
                        aria-label={anchorLabel}
                        className="ml-2 text-muted no-underline opacity-0 transition-opacity group-hover:opacity-100"
                    >
                        #
                    </a>
                ) : null}
            </Tag>
        )
    }

/**
 * One "Interview Arc" section (see `remarkArcSections` in `./index`): the label
 * (`children[0]`, already rendered by `mutedblock`/the `p` fake-heading case) boxed
 * with its body. The first two sections in authoring order (TL;DR, mechanism ΓÇö see
 * `.claude/docs/rules/flashcard-answer.md` ┬º2) stay always-expanded and divider-
 * separated; the rest start collapsed behind a label chip so a 4-5 section answer
 * doesn't read as one long crammed scroll. `stopPropagation` on the chip because
 * `FlipCard`'s whole face is a click-to-flip target ΓÇö an un-stopped click would flip
 * the card back to front instead of expanding the section.
 * @param props.index - 0-based position among arc sections in this answer.
 * @param props.children - `[label, ...body]`, as grouped by the remark transform.
 */
const ArcSection = ({ index, children }: { index?: number, children?: React.ReactNode }) => {
    const position = index ?? 0
    const isCore = position < 2
    const [expanded, setExpanded] = React.useState(isCore)
    // the label is `children[0]` (a `<strong>` for the lead-bold-paragraph shape, or
    // the whole `mutedblock` div for the `:::muted` shape) ΓÇö force it onto its own
    // line as a small MUTED "eyebrow" (teacher, 2026-07-12: label = `text-xs text-muted`,
    // no per-section colour ΓÇö the section labels are authored inconsistently so a
    // colour-by-label map rendered wrong; a uniform muted label reads cleaner).
    // `!` = guaranteed win over whatever colour/size the label's own renderer gave it.
    const boxClassName = `[&>*:first-child]:!block [&>*:first-child]:!text-muted [&>*:first-child]:!text-xs [&>*:first-child]:!font-medium [&>*:first-child]:!mb-1 border-l-2 border-default pl-3 ${position > 0 ? "mt-3" : ""}`
    if (expanded) {
        // the lead-bold-paragraph shape keeps its " ΓÇö " separator right after the
        // label text ΓÇö drop it now that the label sits on its own line above.
        const list = React.Children.toArray(children)
        if (typeof list[1] === "string") {
            list[1] = (list[1] as string).replace(/^\s*[ΓÇö-]\s*/, "")
        }
        return <div className={boxClassName}>{list}</div>
    }
    const label = React.Children.toArray(children)[0]
    return (
        <button
            type="button"
            onClick={(event) => {
                event.stopPropagation()
                setExpanded(true)
            }}
            className="mr-2 mt-2 inline-flex items-center gap-1 rounded-full bg-default px-2 py-1 text-xs text-muted transition-colors hover:bg-default/80"
        >
            {getNodeText(label)}
            <CaretDownIcon weight="bold" className="size-4" />
        </button>
    )
}

/**
 * Builds the element-renderer map handed to `ReactMarkdown` so headings, tables, code
 * blocks, mermaid diagrams and inline elements use the app's HeroUI typography.
 *
 * Vertical rhythm is owned by the single `space-y` wrapper in {@link MarkdownContent}; block
 * renderers here stay margin-free and only carry size/weight/colour tokens.
 * @param params - {@link MarkdownRenderersParams} theme flag + translator + mermaid captions.
 * @returns A `Components` map keyed by markdown element name.
 */
export const buildMarkdownRenderers = ({
    isDark,
    t,
    mermaidCaptions,
    reading = false,
    plain = false,
    codeElevated = false,
}: MarkdownRenderersParams): Components => {
    // Long-form lessons read the larger scale; cards / chat / modals keep the compact one.
    const bodySize = reading ? "base" : "sm"
    const h2Size = reading ? PROSE_SIZE["2xl"] : PROSE_SIZE.lg
    const h3Size = reading ? PROSE_SIZE.xl : PROSE_SIZE.base
    // Reading-only asymmetric rhythm: a heading carries MORE space above than below so it
    // reads as a new section binding to the text under it (Tailwind-prose style). Compact
    // mode leaves block renderers margin-free and relies on the wrapper's uniform space-y.
    const h2Margin = reading ? "mt-10 mb-3" : ""
    const h3Margin = reading ? "mt-8 mb-3" : ""
    const blockMy = reading ? "my-4" : ""
    // Heading deep-link anchor only in reading mode (cards / chat have no shareable url).
    const anchorLabel = reading ? t("markdown.headingAnchor") : ""
    return ({
        h1: ({ children }) => (
            <ProseText elementType="h1" size={reading ? "2xl" : "xl"} className={reading ? "mb-4 font-semibold" : "font-semibold"}>{children}</ProseText>
        ),
        h2: buildTocHeading(2, h2Size, h2Margin, anchorLabel),
        h3: buildTocHeading(3, h3Size, h3Margin, anchorLabel),
        // TOC caps at 3 levels (h2/h3/h4). Reading h4 goes through the TOC factory (id + data-toc
        // + anchor) so 2.1.x sub-sections show in the rail; compact (cards/chat, no TOC) stays muted.
        h4: reading
            ? buildTocHeading(4, PROSE_SIZE.base, "mt-6 mb-2", anchorLabel)
            : ({ children }) => <ProseText elementType="h4" size="sm" className="font-semibold text-muted">{children}</ProseText>,
        // h5 stays a readable heading in the article (foreground + weight in reading) but is NOT in
        // the TOC ΓÇö deeper than 3 levels (e.g. 2.1.3.2 ΓåÆ h5) would over-nest the outline rail.
        h5: ({ children }) => (
            reading
                ? <ProseText elementType="h5" size="sm" className="mt-4 mb-2 font-semibold">{children}</ProseText>
                : <ProseText elementType="h5" size="sm" className="font-semibold text-muted">{children}</ProseText>
        ),
        h6: ({ children }) => (
            reading
                ? <ProseText elementType="h6" size="sm" className="mt-4 mb-2 font-semibold text-muted">{children}</ProseText>
                : <ProseText elementType="h6" size="xs" className="font-semibold text-muted">{children}</ProseText>
        ),
        // Custom `:::muted` directive tags (see remarkMuted in ./index): small, muted label text.
        // `[&_*]:text-muted` forces the muted colour onto any inner `<p>` the container wraps.
        mutedblock: ({ children }: { children?: React.ReactNode }) => (
            <ProseText elementType="div" size="sm" className="font-semibold text-muted [&_*]:text-muted">{children}</ProseText>
        ),
        mutedtext: ({ children }: { children?: React.ReactNode }) => (
            <ProseText elementType="span" size="sm" className="font-semibold text-muted">{children}</ProseText>
        ),
        // `:::muted`/bold-label + its body, boxed as one Interview Arc section ΓÇö opt-in via
        // `MarkdownContent`'s `arcSections` prop (see remarkArcSections in ./index).
        arcsection: ArcSection,
        // Custom `:::chip` directive tag (see remarkChip in ./index): a wrapped row of soft chips,
        // one per authored keyword line. `items` is the `|`-joined keyword list.
        chipblock: ({ items }: { items?: string }) => (
            <span data-principle="sibling-stack" className="my-2 flex flex-wrap gap-2">
                {String(items ?? "").split("|").filter(Boolean).map((keyword, index) => (
                    <HeroUI.Chip key={index} size="sm" variant="soft" color="default">{keyword}</HeroUI.Chip>
                ))}
            </span>
        ),
        // :::tab ΓåÆ [ Preview | Code ] tabs; code/preview panes carry `kind` so TabsBlock can match them.
        tabblock: ({ children }: { children?: React.ReactNode }) => <TabsBlock>{children}</TabsBlock>,
        tabcode: ({ children }: { children?: React.ReactNode }) => <TabPane kind="code">{children}</TabPane>,
        tabpreview: ({ children }: { children?: React.ReactNode }) => <TabPane kind="preview">{children}</TabPane>,
        // ::::accordion / :::panel{title} ΓåÆ HeroUI collapsible accordion (see remarkAccordion in ./index).
        // Matches the `LabeledAccordionCard` skin (accordion.md ┬º3e): `variant="default"` keeps the item
        // separator FULL-BLEED (`left-0 w-full`; surface would inset it to 3%), with the light hairline
        // `--separator` re-point so dividers read the same as the SurfaceListCard family. Default bakes no
        // bg/radius, so add `bg-surface rounded-3xl` here; `border` delineates it as a nested surface
        // (reading column / step card) where a shadow can vanish in dark mode.
        accordionblock: ({ children }: { children?: React.ReactNode }) => (
            <HeroUI.Accordion
                variant="default"
                style={{ "--separator": "color-mix(in oklab, var(--surface-foreground) 6%, transparent)" } as React.CSSProperties}
                className={`${reading ? "my-4" : "my-2"} overflow-hidden rounded-3xl border border-default bg-surface`}
            >{children}</HeroUI.Accordion>
        ),
        accordionpanel: ({ title, children }: { title?: string, children?: React.ReactNode }) => (
            <HeroUI.Accordion.Item aria-label={String(title ?? "")}>
                <HeroUI.Accordion.Heading>
                    <HeroUI.Accordion.Trigger>
                        <div className="flex w-full items-center justify-between gap-3 text-start">
                            <span className={reading ? "text-base font-semibold" : "text-sm font-semibold"}>{title}</span>
                            <HeroUI.Accordion.Indicator />
                        </div>
                    </HeroUI.Accordion.Trigger>
                </HeroUI.Accordion.Heading>
                <HeroUI.Accordion.Panel>
                    <HeroUI.Accordion.Body>
                        <div className="space-y-2">{children}</div>
                    </HeroUI.Accordion.Body>
                </HeroUI.Accordion.Panel>
            </HeroUI.Accordion.Item>
        ),
        table: ({ children }) => (
            <MarkdownTable ariaLabel={t("markdown.tableAriaLabel")} className={blockMy}>
                {children}
            </MarkdownTable>
        ),
        thead: MarkdownTableHead,
        img: ({ src, alt }) => (
            // Markdown `![caption](src)`: a non-empty alt doubles as a real figure caption;
            // an empty alt renders a bare (decorative) image.
            alt ? (
                <figure className={reading ? "my-4" : undefined}>
                    <img src={src} alt={alt} className="w-full rounded-xl border border-default" />
                    <figcaption className="mt-2 text-center text-sm italic text-muted">{alt}</figcaption>
                </figure>
            ) : (
                <img src={src} alt="" className={`${reading ? "my-4 " : ""}w-full rounded-xl border border-default`} />
            )
        ),
        tbody: MarkdownTableBody,
        th: MarkdownTableColumn,
        td: ({ children }) => <Table.Cell>{children}</Table.Cell>,
        tr: MarkdownTableRow,
        code: (
            { children, node }
        ) => {
            const code = String(children).trim()
            const isInline = node ? isInlineCode(node) : undefined
            if (!isInline) {
                return children
            }
            // plain mode: inline code renders as its raw text (no mono/background) ΓÇö
            // teacher, 2026-07-17: "render it raw" for flashcard + mock interview.
            if (plain) {
                return <>{code}</>
            }
            // Neutral inline code (GitHub/Stripe-style): subtle surface + foreground text, NOT
            // the brand accent ΓÇö accent is reserved for links so a keyword-dense paragraph stays calm.
            return (
                <code className="rounded-md bg-default px-1 py-0 font-mono text-sm text-foreground [overflow-wrap:anywhere]">
                    {code}
                </code>
            )
        },
        pre: ({ children }) => {
            const child = React.Children.only(children) as React.ReactElement
            const className = (child.props as { className?: string }).className || ""
            const match = /language-(\w+)/.exec(className)
            const lang = match?.[1] || "bash"
            const code = String((child.props as { children?: React.ReactNode }).children || "").replace(/\n$/, "")
            if (lang.toLowerCase() === "mermaid") {
                return (
                    <MermaidDiagram
                        code={code}
                        theme={isDark ? "dark" : "default"}
                        loadingLabel={t("markdown.mermaidRendering")}
                        expandLabel={t("markdown.mermaidExpand")}
                        caption={mermaidCaptions[code.trim()]}
                        fallbackLabel={t("markdown.mermaidFigureLabel")}
                        className={blockMy}
                    />
                )
            }
            // ```mdx fence ΓåÆ live HeroUI render (render-only; tabs come from a :::tab block).
            if (lang.toLowerCase() === "mdx") {
                return <RenderReactComponent code={code} />
            }
            if (lang.toLowerCase() === "layout") {
                return <LayoutWidget html={code} />
            }
            return (
                <CodeToHtml
                    code={code}
                    language={lang}
                    theme={isDark
                        ? "material-theme-darker"
                        : "material-theme-lighter"}
                    elevated={codeElevated}
                    className={blockMy}
                />
            )
        },
        blockquote: ({ children }) => (
            <blockquote className={`${reading ? "my-4 " : ""}space-y-2 rounded-r-xl border-l-2 border-accent bg-default/40 px-4 py-2 text-muted`}>
                {children}
            </blockquote>
        ),
        // Bold = weight only ΓÇö no colour jump ΓÇö so a keyword-heavy paragraph doesn't flicker.
        // plain mode drops the weight/italic entirely ΓåÆ raw text (teacher, 2026-07-17: "render it raw").
        strong: ({ children }) => (plain ? <>{children}</> : <strong className="font-semibold">{children}</strong>),
        em: ({ children }) => (plain ? <>{children}</> : <em className="italic">{children}</em>),
        hr: () => <hr className={`${reading ? "my-6 " : ""}border-default`} />,
        ol: ({ children }) => <ol className={`${reading ? "my-4 " : ""}list-decimal space-y-2 pl-5 marker:text-muted`}>{children}</ol>,
        ul: ({ children }) => <ul className={`${reading ? "my-4 " : ""}list-disc space-y-2 pl-5 marker:text-muted`}>{children}</ul>,
        li: ({ children }) => (
            <ProseText elementType="li" size={bodySize} className="space-y-2 leading-relaxed">{children}</ProseText>
        ),
        p: ({ children, node }) => {
            // a paragraph whose ENTIRE content is one `**bold**` span is a common
            // "fake heading" authoring idiom (e.g. flashcard answers structured
            // "**Direct answer** ...", "**Why** ...") ΓÇö read it as a section
            // LABEL (muted, small), not a normal bold sentence, so it lines up
            // with the surrounding UI labels ("Question"/"Answer" are
            // `body-xs muted`) instead of standing out as loud black bold.
            const soleChild = node?.children?.length === 1 ? node.children[0] : null
            const isStandaloneLabel = Boolean(
                soleChild && "tagName" in soleChild && soleChild.tagName === "strong",
            )
            if (isStandaloneLabel) {
                return <div className="text-sm text-muted">{children}</div>
            }
            return (
                <ProseText elementType="div" size={bodySize} className={reading ? "mb-4 leading-relaxed" : "leading-relaxed"}>{children}</ProseText>
            )
        },
        a: ({ href, children }) => {
        // plain mode: strip the link chrome (accent + underline) ΓåÆ raw text (teacher, 2026-07-17).
            if (plain) {
                return <>{children}</>
            }
            // Internal links (e.g. related-problem `/practice/<slug>`) navigate in-app
            // (same tab, locale-aware) via the next-intl Link; external links open a new tab.
            const isInternal = typeof href === "string" && href.startsWith("/")
            if (isInternal) {
                return (
                    <IntlLink href={href} className="!inline text-accent-soft-foreground underline underline-offset-4 decoration-[var(--separator-tertiary)]">
                        {children}
                    </IntlLink>
                )
            }
            return (
                <Link href={href} target="_blank" className="!inline text-accent-soft-foreground underline underline-offset-4 decoration-[var(--separator-tertiary)]">
                    {children}
                </Link>
            )
        },
    } as Components)
}

import React from "react"
import { Skeleton, cn } from "@heroui/react"
