/**
 * `PersonalProjectWorkspace` ΓÇö the CONNECTED half of the SRC TWIN of
 * `.storybook/components/starci/pages/PersonalProjectWorkspace`. Mirrors the data
 * wiring already proven in `src/components/features/learn/PersonalProject`
 * (the v1 `PersonalProjectWorkspace` + its `PersonalProjectDashboard`, `Task`/
 * `TaskSubmissionPanel` split, and `TaskResult`) onto the storybook-driven screen
 * tree in `./component` instead of that v1's hand-built layout ΓÇö same routes
 * (`/learn/personal-projectΓÇª`, NOT swapped here), same redux/SWR/zustand sources.
 *
 * STAGED, route NOT swapped ΓÇö this twin is built and mounted nowhere yet
 * (`src-tier-ported-but-unused`, matching batches 1ΓÇô16). The live routes still
 * render the v1 `PersonalProjectWorkspace`; deleting v1 or swapping the route is
 * deferred debt, handled by a later batch.
 *
 * Like the blueprint and v1, this is a THREE-LEAF structural switch keyed off the
 * URL (not a data state of one shape): no `taskId` ΓåÆ `dashboard`; a `taskId` whose
 * path ends in `/result` ΓåÆ `result`; otherwise ΓåÆ `task`. Each leaf is its own
 * connected sub-component so its hooks run only when that leaf is mounted (rules of
 * hooks ΓÇö the three view fetch surfaces never share one component).
 */
export const PersonalProjectWorkspaceLayout = () => {
    const params = useParams()
    const pathname = usePathname()
    const taskId = typeof params?.taskId === "string" ? params.taskId : undefined
    const isResult = /\/result\/?$/.test(pathname)

    if (!taskId) {
        return <DashboardView />
    }
    if (isResult) {
        return <ResultView taskId={taskId} />
    }
    return <TaskView taskId={taskId} />
}

/** github.com URL ΓåÆ `owner/repo` (drops scheme + trailing .git) for a compact label. */
const toRepoLabel = (url: string): string =>
    url
        .trim()
        .replace(/^https?:\/\/(www\.)?github\.com\//i, "")
        .replace(/\.git$/i, "")
        .replace(/\/$/, "")

/** MilestoneSeverity enum ΓåÆ the presentational block's severity union. */
const SEVERITY_TO_TWIN: Record<MilestoneSeverity, SubmissionFeedbackSeverity> = {
    [MilestoneSeverity.High]: "high",
    [MilestoneSeverity.Medium]: "medium",
    [MilestoneSeverity.Low]: "low",
}

/** v1 AiModelCategory enum ΓåÆ the presentational block's category union (same string values). */
const MODEL_CATEGORY_TO_TWIN: Record<AiModelCategory, SubmissionModelCategory> = {
    [AiModelCategory.Medium]: "medium",
    [AiModelCategory.High]: "high",
    // Low is the chat rung and the embedding tiers never grade ΓÇö folded to the
    // lowest grading chip so the record stays exhaustive over the enum
    [AiModelCategory.Low]: "low",
    [AiModelCategory.EmbeddingBulk]: "low",
    [AiModelCategory.EmbeddingDoc]: "low",
}

/**
 * Map raw `searchCourseContent` hits into the presentational `ContentRelatedItem`
 * rows ΓÇö mirrors `RelatedContentList`'s own filter/slice/resolve, but returns DATA
 * (the block expects resolved rows, not a self-contained search). Drops the current
 * surface's own source and any hit whose kind lacks the ids it needs to route.
 */
const toRelatedItems = (
    results: Array<SearchCourseContentItem>,
    locale: Locale,
    courseDisplayId: string,
    excludeId: string | undefined,
    limit = 3,
): Array<ContentRelatedItem> =>
    results
        .filter((item) => !excludeId
            || (item.contentId !== excludeId && item.deckId !== excludeId && item.taskId !== excludeId))
        .slice(0, limit)
        .map((item, index): ContentRelatedItem | null => {
            const href = resolveSearchResultHref(item, locale, courseDisplayId)
            if (!href) {
                return null
            }
            return {
                key: `${item.kind}-${item.contentId ?? item.deckId ?? item.taskId ?? index}`,
                title: item.title,
                breadcrumb: item.breadcrumb ?? undefined,
                isLocked: item.isLocked,
                href,
            }
        })
        .filter((row): row is ContentRelatedItem => row != null)

/** Home ΓÇ║ Courses ΓÇ║ <course> ΓÇ║ Capstone breadcrumb rows, structurally usable by every leaf. */
const useLearnCrumbs = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const course = useAppSelector((state) => state.course.entity)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)

    return useMemo(() => [
        {
            key: "home",
            label: t("nav.home"),
            onPress: () => router.push(pathConfig().locale().build()),
        },
        {
            key: "courses",
            label: t("nav.courses"),
            onPress: () => router.push(pathConfig().locale(locale).course().build()),
        },
        {
            key: "course",
            label: course?.title || t("nav.courses"),
            onPress: () => router.push(pathConfig().locale(locale).course(courseDisplayId).build()),
        },
        {
            key: "capstone",
            label: t("course.finalProjectTitle"),
        },
    ], [t, locale, router, course?.title, courseDisplayId])
}

/**
 * `view="dashboard"` ΓÇö the capstone landing overview. Lifts the wiring of the v1
 * `PersonalProjectDashboard` (milestones + progress SWR, enrollment GitHub status,
 * the next-task/current-milestone/stats derivations) into the presentational
 * dashboard block's prop surface.
 */
const DashboardView = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const crumbs = useLearnCrumbs()

    const milestonesSwr = useQueryMilestonesSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const enrollment = useAppSelector((state) => state.user.enrollment)
    const githubUrl = enrollment?.personalProjectGithubUrl ?? ""
    const githubBranch = enrollment?.personalProjectGithubBranch ?? ""

    const milestones = useMemo(
        () => [...milestoneEntities].sort((prev, next) => prev.sortIndex - next.sortIndex),
        [milestoneEntities],
    )
    const completionTasks = progressSwr.data?.milestoneTaskProgress?.data?.completionTasks
    const progressMap = useMemo(
        () => buildMilestoneTaskProgressLookup(completionTasks),
        [completionTasks],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    const currentTask = useMemo(() => {
        if (!currentTaskId) {
            return undefined
        }
        for (const milestone of milestones) {
            const task = (milestone.tasks ?? []).find((entity) => entity.id === currentTaskId)
            if (task) {
                return task
            }
        }
        return undefined
    }, [milestones, currentTaskId])

    const currentMilestone = useMemo(() => {
        if (currentTaskId) {
            const owning = milestones.find((milestone) =>
                (milestone.tasks ?? []).some((task) => task.id === currentTaskId))
            if (owning) {
                return owning
            }
        }
        return milestones[0]
    }, [milestones, currentTaskId])

    const stats = useMemo(() => {
        let total = 0
        for (const milestone of milestones) {
            total += (milestone.tasks ?? []).length
        }
        let done = 0
        let attempts = 0
        let scoreSum = 0
        let maxSum = 0
        let scored = 0
        for (const item of completionTasks ?? []) {
            attempts += item.numAttempts ?? 0
            if (item.completed) {
                done += 1
                if (typeof item.lastScore === "number") {
                    scoreSum += item.lastScore
                    maxSum += item.maxScore ?? 20
                    scored += 1
                }
            }
        }
        const avgScore = scored > 0 ? Math.round(scoreSum / scored) : null
        const avgMax = scored > 0 ? Math.round(maxSum / scored) : 20
        return {
            done,
            total,
            attempts,
            avgLabel: avgScore != null ? `${avgScore}/${avgMax}` : "ΓÇö",
        }
    }, [milestones, completionTasks])

    const isConnected = githubUrl.trim().length > 0
    const githubLabel = isConnected
        ? `${toRepoLabel(githubUrl)} ┬╖ ${githubBranch || "main"}`
        : t("finalProject.dashboard.notConnected")

    const onContinue = useCallback(() => {
        const nextId = currentTaskId ?? milestones[0]?.tasks?.[0]?.id
        if (!nextId) {
            return
        }
        dispatch(setSelectedTaskId(nextId))
        router.push(
            pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(nextId).build(),
        )
    }, [currentTaskId, milestones, dispatch, router, locale, courseDisplayId])

    const onSelectTask = useCallback(
        (id: string) => {
            dispatch(setSelectedTaskId(id))
            router.push(
                pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(id).build(),
            )
        },
        [dispatch, router, locale, courseDisplayId],
    )

    const tasks = useMemo((): Array<PersonalProjectDashboardTask> =>
        (currentMilestone?.tasks ?? []).map((task) => {
            const isCompleted = progressMap.get(task.id)?.completed ?? false
            const isActive = task.id === currentTaskId
            const isLocked = !isPersonalProjectTaskActionUnlocked(task.id, progressMap, currentTaskId)
            const subtitleState: PersonalProjectTaskSubtitleState = isActive
                ? "active"
                : isCompleted
                    ? "done"
                    : isLocked
                        ? "locked"
                        : "todo"
            return {
                id: task.id,
                sortIndex: task.sortIndex,
                title: task.title,
                subtitleState,
            }
        }),
    [currentMilestone?.tasks, progressMap, currentTaskId])

    const hasMilestones = milestones.length > 0
    const isLoading = (!hasMilestones && !milestonesSwr.error && (milestonesSwr.isLoading || !milestonesSwr.data))
        || (progressSwr.isLoading && !progressSwr.data)
    const isEmpty = !hasMilestones && !milestonesSwr.isLoading && !!milestonesSwr.data && !milestonesSwr.error

    return (
        <_PersonalProjectWorkspaceLayout
            view="dashboard"
            breadcrumbItems={crumbs}
            title={t("finalProject.dashboard.title")}
            description={t("finalProject.dashboard.subtitle")}
            githubStatus={{ isConnected, label: githubLabel }}
            currentTask={currentTask ? { sortIndex: currentTask.sortIndex, title: currentTask.title } : undefined}
            onContinue={onContinue}
            milestoneLabel={currentMilestone?.title}
            tasks={tasks}
            onSelectTask={onSelectTask}
            stats={stats}
            isLoading={isLoading}
            isEmpty={isEmpty}
            isSkeleton={enrollment == null}
        />
    )
}

/**
 * `view="task"` ΓÇö the read-left/act-right task solve split. Lifts the wiring of the
 * v1 `Task` reading column (redux task detail + per-language brief + legacy
 * rubric/guides + related lessons) and the `TaskSubmissionPanel` act column (the
 * shared GitHub form store + the `TaskActions` gating + the latest graded result).
 *
 * The grading-settings drawer and the attempts-history drawer are NOT built in this
 * twin (see the recorded debt): `onOpenSettings`/`onOpenAttempts` are chrome-only
 * no-ops here, and the v1 AI-processing status line has no presentational surface.
 */
const TaskView = ({ taskId }: { taskId: string }) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const dispatch = useAppDispatch()
    const crumbs = useLearnCrumbs()

    // URL is the source of truth for which task is open ΓÇö sync it into redux the same
    // way the v1 dashboard/rail select does, so every colocated hook reads the id.
    useEffect(() => {
        dispatch(setSelectedTaskId(taskId))
    }, [dispatch, taskId])

    const milestoneTaskQuery = useQueryMilestoneTaskSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const attemptsSwr = useQueryUserPersonalTaskAttemptsSwr()
    const aiModelsSwr = useQueryAiModelsSwr()
    const syncGithubSwr = useMutateSyncPersonalProjectGithubSwr()
    const syncBranchSwr = useMutateSyncPersonalProjectGithubBranchSwr()
    const githubForm = usePersonalProjectGithubForm({ enableSync: true })

    const course = useAppSelector((state) => state.course.entity)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const milestoneTaskIdToJobId = useAppSelector((state) => state.milestone.milestoneTaskIdToJobId)
    const jobStatusByJobId = useAppSelector((state) => state.socketIo.jobStatusByJobId)

    const displayTask = useMemo(() => {
        if (selectedTaskDetail?.id === taskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === taskId)
            if (found) {
                return found
            }
        }
        return undefined
    }, [taskId, selectedTaskDetail, milestoneEntities])

    // Locked-preview gate ΓÇö same derivation as v1 TaskLockedAlert / TaskActions.
    const progressMap = useMemo(
        () => buildMilestoneTaskProgressLookup(progressSwr.data?.milestoneTaskProgress?.data?.completionTasks),
        [progressSwr.data],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id
    const isActionUnlocked = useMemo(() => {
        if (progressSwr.isLoading) {
            return true
        }
        return isPersonalProjectTaskActionUnlocked(taskId, progressMap, currentTaskId)
    }, [taskId, progressMap, currentTaskId, progressSwr.isLoading])
    const isLocked = !isActionUnlocked

    // Brief: schema-v2 authored body for the active grading language, else "" (legacy tasks).
    const briefs = displayTask?.briefs ?? []
    const briefBody = useMemo(() => {
        const picked = briefs.find((brief) => brief.lang === githubForm.lang) ?? briefs[0]
        return picked?.body ?? ""
    }, [briefs, githubForm.lang])

    // Legacy rubric + per-language implementation guides ΓÇö only when there is NO brief.
    const hasBrief = briefs.length > 0
    const legacyCriteria = useMemo((): Array<PersonalProjectTaskLegacyCriterionItem> | undefined => {
        if (hasBrief) {
            return undefined
        }
        return [...(displayTask?.criterias ?? [])]
            .sort((prev, next) => prev.sortIndex - next.sortIndex)
            .map((criteria) => ({
                key: criteria.id,
                text: criteria.text,
                score: criteria.score,
                hint: criteria.hint || undefined,
            }))
    }, [hasBrief, displayTask?.criterias])
    const legacyCodeImplementations = useMemo((): Array<PersonalProjectTaskLegacyCodeImplementationItem> | undefined => {
        if (hasBrief) {
            return undefined
        }
        return (displayTask?.codeImplementations ?? []).map((impl) => ({
            key: impl.id,
            lang: impl.lang,
            guide: impl.guide,
            example: impl.example,
        }))
    }, [hasBrief, displayTask?.codeImplementations])

    // Related reading ΓÇö RAG search off the task's own title/description (no typing), mapped to rows.
    const relatedQuery = displayTask?.title
        ? `${displayTask.title} ${displayTask.description ?? ""}`
        : ""
    const relatedSwr = useQuerySearchCourseContentSwr(course?.id ?? null, relatedQuery, Boolean(course?.id && relatedQuery.trim()))
    const relatedItems = useMemo(
        () => toRelatedItems(relatedSwr.data ?? [], locale, course?.displayId ?? "", displayTask?.id),
        [relatedSwr.data, locale, course?.displayId, displayTask?.id],
    )

    // Act column ΓÇö GitHub form + evaluate gating (TaskActions) + latest graded result (TaskResults).
    const attemptRows = useMemo(() => attemptsSwr.data?.data ?? [], [attemptsSwr.data?.data])
    const hasAttempts = attemptRows.length > 0
    const latestAttempt = attemptRows[0]

    const reviewJobId = milestoneTaskIdToJobId[taskId]
    const reviewJobStatus = reviewJobId ? jobStatusByJobId[reviewJobId]?.data?.status : undefined

    const isEvaluateDisabled = !isActionUnlocked
        || githubForm.isSubmitting
        || attemptsSwr.isLoading
        || syncGithubSwr.isMutating
        || syncBranchSwr.isMutating
    const isEvaluatePending = githubForm.isSubmitting
        || (Boolean(reviewJobId) && (reviewJobStatus === JobStatus.Processing || reviewJobStatus === JobStatus.Queued))

    const langLabelMap: Record<string, string> = {
        typescript: t("programmingLanguage.typescript"),
        java: t("programmingLanguage.java"),
        csharp: t("programmingLanguage.csharp"),
        go: t("programmingLanguage.go"),
    }

    const modelCategoryMap = useMemo(() => {
        const map = new Map<string, SubmissionModelCategory>()
        for (const model of aiModelsSwr.data?.aiModels?.data?.gradableModels ?? []) {
            map.set(model.model, MODEL_CATEGORY_TO_TWIN[model.category])
        }
        return map
    }, [aiModelsSwr.data])

    const panelResult = useMemo(() => {
        if (!latestAttempt) {
            return undefined
        }
        const timeAgo = latestAttempt.processedAt
            ? getTimeAgoLabel(getTimeAgoMessage(dayjs(latestAttempt.processedAt)), t)
            : undefined
        return {
            score: latestAttempt.score ?? 0,
            maxScore: displayTask?.maxScore ?? undefined,
            isPassing: latestAttempt.passed,
            shortFeedback: latestAttempt.shortFeedback ?? undefined,
            gradedByModel: latestAttempt.servedModel ?? undefined,
            modelCategory: latestAttempt.servedModel ? modelCategoryMap.get(latestAttempt.servedModel) : undefined,
            timeAgo: timeAgo ?? undefined,
        }
    }, [latestAttempt, displayTask?.maxScore, modelCategoryMap, t])

    const onEvaluate = useCallback(() => {
        void githubForm.submit()
    }, [githubForm])
    const onOpenFeedbackDetails = useCallback(() => router.push(`${pathname}/result`), [router, pathname])

    const isSkeleton = !displayTask || milestoneTaskQuery.isLoading

    return (
        <_PersonalProjectWorkspaceLayout
            view="task"
            breadcrumbItems={crumbs}
            task={{ title: displayTask?.title ?? "", description: displayTask?.description || undefined }}
            isLocked={isLocked}
            brief={{ body: briefBody }}
            legacyCriteria={legacyCriteria}
            legacyCodeImplementations={legacyCodeImplementations}
            relatedItems={relatedItems}
            relatedLabel={t("task.relatedContent.label")}
            submissionPanelProps={{
                repoUrl: githubForm.githubUrl,
                onRepoUrlChange: githubForm.setGithubUrl,
                repoUrlError: githubForm.touched.githubUrl ? (githubForm.errors.githubUrl ?? undefined) : undefined,
                settingsLangLabel: langLabelMap[githubForm.lang] ?? githubForm.lang,
                settingsBranch: githubForm.branch,
                // Settings drawer not built in this twin ΓÇö chrome-only no-op (see debt).
                onOpenSettings: () => {},
                onEvaluate,
                isEvaluatePending,
                isEvaluateDisabled,
                hasAttempts,
                onOpenFeedbackDetails,
                // Attempts-history drawer not built in this twin ΓÇö chrome-only no-op (see debt).
                onOpenAttempts: () => {},
                result: panelResult,
            }}
            isSkeleton={isSkeleton}
        />
    )
}

/**
 * `view="result"` ΓÇö the graded-attempt verdict. Lifts the wiring of the v1
 * `PersonalProjectTaskResult` (attempts + feedbacks SWR gated on redux
 * `selectedAttemptId`, the AI-model catalog for the grader byline, the severity
 * sort, the failing-attempt related search, and the passing-attempt next-task
 * handoff) into the presentational result screen's prop surface.
 *
 * The attempts-history overflow drawer is NOT built in this twin (see debt): all
 * attempts are shown inline and no "+N" overflow trigger is surfaced.
 */
const ResultView = ({ taskId }: { taskId: string }) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const searchParams = useSearchParams()
    const dispatch = useAppDispatch()

    useEffect(() => {
        dispatch(setSelectedTaskId(taskId))
    }, [dispatch, taskId])

    useQueryMilestoneTaskSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const attemptsSwr = useQueryUserPersonalTaskAttemptsSwr()
    const feedbacksSwr = useQueryUserPersonalTaskAttemptFeedbacksSwr()
    const aiModelsSwr = useQueryAiModelsSwr()

    const course = useAppSelector((state) => state.course.entity)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const githubUrl = usePersonalProjectGithubStore((state) => state.githubUrl)

    const maxScore = selectedTaskDetail?.maxScore ?? 0
    const attemptParam = searchParams.get("attempt")

    const attempts = useMemo(() => attemptsSwr.data?.data ?? [], [attemptsSwr.data])
    const selectedAttempt = useMemo(
        () => (attemptParam ? attempts.find((attempt) => attempt.id === attemptParam) : undefined) ?? attempts[0],
        [attempts, attemptParam],
    )

    // The feedbacks hook is gated on redux `selectedAttemptId` ΓÇö keep it in sync.
    useEffect(() => {
        dispatch(setSelectedAttemptId(selectedAttempt?.id))
    }, [dispatch, selectedAttempt?.id])

    const feedbacks = useMemo(() => feedbacksSwr.data?.data ?? [], [feedbacksSwr.data])
    const passing = selectedAttempt?.passed ?? false

    const modelCategoryMap = useMemo(() => {
        const map = new Map<string, SubmissionModelCategory>()
        for (const model of aiModelsSwr.data?.aiModels?.data?.gradableModels ?? []) {
            map.set(model.model, MODEL_CATEGORY_TO_TWIN[model.category])
        }
        return map
    }, [aiModelsSwr.data])
    const servedCategory = selectedAttempt?.servedModel ? modelCategoryMap.get(selectedAttempt.servedModel) : undefined

    const attemptItems = useMemo((): Array<SubmissionAttempt> =>
        attempts.map((attempt) => ({
            id: attempt.id,
            attemptNumber: attempt.attemptNumber,
            score: attempt.score,
            isPassing: attempt.passed,
        })),
    [attempts])

    const findings = useMemo((): Array<SubmissionFinding> =>
        feedbacks.map((feedback) => ({
            id: feedback.id,
            message: feedback.message,
            suggestion: feedback.suggestion ?? undefined,
            location: feedback.location ?? undefined,
            severity: SEVERITY_TO_TWIN[feedback.severity] ?? "medium",
            sortIndex: feedback.sortIndex,
        })),
    [feedbacks])

    // Next milestone task once this one passes ΓÇö look its title up across the tree.
    const nextTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id ?? undefined
    const nextTask = useMemo(() => {
        if (!passing || !nextTaskId || nextTaskId === taskId) {
            return undefined
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === nextTaskId)
            if (found) {
                return { title: found.title }
            }
        }
        return undefined
    }, [passing, nextTaskId, taskId, milestoneEntities])
    const onGoToNextTask = useCallback(() => {
        if (!nextTaskId || !courseDisplayId) {
            return
        }
        router.push(
            pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(nextTaskId).build(),
        )
    }, [nextTaskId, courseDisplayId, locale, router])

    // Related reading ΓÇö only meaningful on a FAILED attempt; query auto-built from the top findings.
    const failingQuery = useMemo(
        () => [...findings]
            .sort((a, b) => (a.severity === b.severity ? (a.sortIndex ?? 0) - (b.sortIndex ?? 0) : 0))
            .slice(0, 3)
            .map((finding) => finding.message)
            .join(" "),
        [findings],
    )
    const relatedSwr = useQuerySearchCourseContentSwr(
        course?.id ?? null,
        failingQuery,
        Boolean(!passing && course?.id && failingQuery.trim()),
    )
    const relatedItems = useMemo(
        () => (passing ? [] : toRelatedItems(relatedSwr.data ?? [], locale, courseDisplayId ?? "", taskId)),
        [passing, relatedSwr.data, locale, courseDisplayId, taskId],
    )

    const timeAgo = selectedAttempt?.processedAt
        ? getTimeAgoLabel(getTimeAgoMessage(dayjs(selectedAttempt.processedAt)), t)
        : undefined

    const taskHref = pathname.replace(/\/result\/?$/, "")
    const onBack = useCallback(() => router.push(taskHref), [router, taskHref])
    const onSelectAttempt = useCallback(
        (id: string) => router.push(`${pathname}?attempt=${id}`),
        [router, pathname],
    )

    const attemptsLoading = attemptsSwr.data == null ? !attemptsSwr.error : false

    return (
        <_PersonalProjectWorkspaceLayout
            view="result"
            backLabel={t("personalProjectResult.backToTask")}
            onBack={onBack}
            title={selectedTaskDetail?.title ?? t("personalProjectResult.title")}
            description={selectedTaskDetail?.description || undefined}
            attempts={attemptItems}
            selectedAttemptId={selectedAttempt?.id}
            onSelectAttempt={onSelectAttempt}
            attemptsAriaLabel={t("personalProjectResult.history")}
            scoreLabel={t("personalProjectResult.resultLabel")}
            score={selectedAttempt?.score ?? undefined}
            maxScore={maxScore > 0 ? maxScore : undefined}
            isPassing={passing}
            shortFeedback={selectedAttempt?.shortFeedback ?? undefined}
            submissionUrl={githubUrl || undefined}
            gradedByModel={selectedAttempt?.servedModel ?? undefined}
            modelCategory={servedCategory}
            timeAgo={timeAgo}
            findingsLabel={t("personalProjectResult.feedbackLabel")}
            findings={findings}
            repositoryUrl={githubUrl || undefined}
            relatedItems={relatedItems}
            relatedLabel={t("personalProjectResult.relatedContent.label")}
            nextTask={nextTask}
            onGoToNextTask={onGoToNextTask}
            isSkeleton={attemptsLoading}
        />
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    type ReactNode,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useParams,
    usePathname,
    useRouter,
    useSearchParams,
} from "next/navigation"
import { toast } from "@/modules/toast/toast"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryPublicUserCvSwr } from "@/hooks/swr/api/graphql/queries/useQueryPublicUserCvSwr"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { useProfileFollow } from "@/hooks/profile/useProfileFollow"
import type { ProfileTab } from "@/components/blocks/navigation/ProfileTabsBar"
import { toPublicProfileUser } from "./map"
import { _PublicProfileLayout } from "./component"

/** One tab's route path, keyed by locale + the viewed user's username ΓÇö mirrors the real `ProfileTabsBar`'s own `tabHref`. */
const tabHref = (locale: string, username: string, tabId: ProfileTab): string => {
    const profile = pathConfig().locale(locale).profile(username)
    switch (tabId) {
    case "overview":
        return profile.overview().build()
    case "projects":
        return profile.projects().build()
    case "challenges":
        return profile.challenges().build()
    case "skills":
        return profile.skills().build()
    case "activity":
        return profile.activity().build()
    case "cv":
        return profile.cv().build()
    }
}

/** Every profile tab, in the order the strip checks a route-prefix match ΓÇö ported from the real `PROFILE_TABS` minus "overview" (the fallback). */
const ROUTABLE_TABS: ReadonlyArray<ProfileTab> = ["projects", "challenges", "skills", "cv", "activity"]

/**
 * Public-profile shell ΓÇö the CONNECTED half of `_PublicProfileLayout`. Mounted by
 * `app/[locale]/profile/[username]/layout.tsx` (the wiring-in is a later step ΓÇö
 * out of THIS pilot's scope, see task scope limit). Reads the target user + their
 * public CV via SWR (deduped with the rest of the page), derives `isSelf` /
 * `isLoading` / the active tab from the route, owns the follow toggle, and
 * canonicalizes `/profile/<email-or-legacy-handle>` to `/profile/<username>` ΓÇö
 * all ported 1:1 from the real `PublicProfile`/`ProfileTabsBar`/`ProfileHero`
 * feature files (see their file headers).
 *
 * Next hands a route layout its nested segment as already-rendered `children`
 * (a `ReactNode`, not a component reference) ΓÇö this file is the one place that
 * boundary is unavoidable. It is immediately wrapped into a zero-prop component
 * so `_PublicProfileLayout` itself only ever takes the buildable `ComponentType`
 * slot RULE 12 requires (never a raw `ReactNode` prop).
 */
export const PublicProfileLayout = ({
    children,
}: {
    children: ReactNode
}) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const routeUsername = useParams().username
    const searchParams = useSearchParams()

    const username = useProfileUsername()
    const viewer = useAppSelector((state) => state.user.user)
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const {
        data: user,
        isLoading,
        isValidating,
    } = useQueryUserProfileSwr(username)
    const { data: publicCv } = useQueryPublicUserCvSwr(user?.username)
    const {
        following,
        isPending: isFollowPending,
        onToggle: onToggleFollow,
    } = useProfileFollow()

    // canonicalize a legacy/email-addressed link to `/profile/<username>` once the
    // profile resolves ΓÇö mirrors the real `PublicProfile`'s own effect.
    useEffect(() => {
        const segment = routeUsername ? String(routeUsername) : null
        if (!segment || !user?.username || segment === user.username) {
            return
        }
        const query = searchParams.toString()
        const target = pathConfig().locale(locale).profile(user.username).build()
        router.replace(query ? `${target}?${query}` : target)
    }, [routeUsername, user?.username, locale, searchParams, router])

    // "my own profile" = the route's username IS the signed-in viewer ΓÇö match by
    // USERNAME first (id namespaces between the projected profile and the redux
    // viewer can differ and falsely read as a visitor), id as fallback.
    const isSelf = !!viewer && !!user
        && ((!!viewer.username && viewer.username === user.username) || viewer.id === user.id)

    // active tab = the routable tab whose path prefixes the current pathname;
    // "overview" is the bare `/profile/<username>` path ΓÇö a prefix of everything ΓÇö
    // so it's only the fallback when nothing deeper matches.
    const activeTab = useMemo<ProfileTab>(() => {
        if (!user?.username) {
            return "overview"
        }
        const match = ROUTABLE_TABS.find((tabId) => {
            const href = tabHref(locale, user.username, tabId)
            return pathname === href || pathname.startsWith(`${href}/`)
        })
        return match ?? "overview"
    }, [user?.username, pathname, locale])

    const onTabChange = useCallback(
        (tab: ProfileTab) => {
            if (!user?.username) {
                return
            }
            router.push(tabHref(locale, user.username, tab))
        },
        [router, locale, user?.username],
    )

    const onEditProfile = useCallback(() => {
        router.push(pathConfig().locale(locale).profile().edit().build())
    }, [router, locale])

    const onHire = useCallback(() => {
        if (user?.githubUsername) {
            window.open(`https://github.com/${user.githubUsername}`, "_blank", "noopener,noreferrer")
        }
    }, [user?.githubUsername])

    // share this profile ΓÇö native share sheet when present, clipboard-copy fallback otherwise;
    // ported from the real `ShareProfileButton`.
    const onShare = useCallback(async () => {
        if (typeof window === "undefined") {
            return
        }
        const url = window.location.href
        const title = user?.displayName?.trim() || user?.username || ""
        if (navigator.share) {
            try {
                await navigator.share({ title, url })
                return
            } catch {
                // dismissed/failed the native sheet ΓåÆ fall through to copy
            }
        }
        try {
            await navigator.clipboard.writeText(url)
            toast.success(t("publicProfile.share.copied"))
        } catch {
            // clipboard blocked ΓåÆ no-op, nothing actionable to show
        }
    }, [user?.displayName, user?.username, t])

    const onGoHome = useCallback(() => {
        router.push(pathConfig().locale(locale).home().build())
    }, [router, locale])

    const onGoCourses = useCallback(() => {
        router.push(pathConfig().locale(locale).course().build())
    }, [router, locale])

    // Next hands the nested route segment as already-rendered `children` ΓÇö wrap it
    // in a zero-prop component so `_PublicProfileLayout` keeps its buildable-slot contract.
    const BodyPanel = useCallback(() => <>{children}</>, [children])

    return (
        <_PublicProfileLayout
            isLoading={isLoading || (isValidating && !user) || (authenticated && !username)}
            user={user ? toPublicProfileUser(user) : null}
            isSelf={isSelf}
            hasPublicCv={Boolean(publicCv)}
            activeTab={activeTab}
            onTabChange={onTabChange}
            following={following}
            isFollowPending={isFollowPending}
            onToggleFollow={onToggleFollow}
            onEditProfile={onEditProfile}
            onHire={onHire}
            onShare={onShare}
            onGoHome={onGoHome}
            onGoCourses={onGoCourses}
            body={BodyPanel}
        />
    )
}

import React from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"

/** All display text, already localized by the connected `MiniCartDrawer`; a story passes i18n keys. */
export interface MiniCartDrawerLabels {
    /** `"${cart.title} ┬╖ ${cart.itemsCount}"`, already interpolated with `count`. */
    header: string
    emptyTitle: string
    emptyDescription: string
    browseCourses: string
    errorTitle: string
    retry: string
    /** `cart.comboActive`/`cart.comboStart`, already picked+interpolated for the current `bundlePercent`. */
    comboLabel: string
    /** `cart.bundleBonus`, already interpolated ΓÇö only shown while `bundlePercent > 0`. */
    bundleBonusChip: string
    /** `cart.comboNextHint`/`cart.comboMaxHint`, already picked+interpolated for `nextTierPercent`. */
    comboHint: string
    total: string
    /** `cart.savings`, already interpolated ΓÇö only shown while `savingsVnd > 0`. */
    savings: string
    /** `cart.installmentHint`, already interpolated ΓÇö only shown while `cheapestMonthlyVnd` is set. */
    installmentHint: string
    checkout: string
    viewFullCart: string
}

/** Props for {@link _MiniCartDrawer} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface MiniCartDrawerProps {
    isOpen: boolean
    onOpenChange: (open: boolean) => void
    /** Slide-in edge. `true` on mobile ΓåÆ bottom sheet. */
    isMobile: boolean
    /** First load, nothing in hand ΓåÆ the cart-list zone shimmers in place (co-located). */
    isSkeleton?: boolean
    /** Settled with zero lines ΓåÆ the empty message replaces the list. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the cart-list zone falls to the error message (beats loading + empty). */
    error?: unknown
    onRetry?: () => void
    onBrowseCourses?: () => void
    items?: Array<CartItemEntity>
    /** courseId ΓåÆ the real checkout-preview line, for per-line pricing. */
    previewByCourse?: Map<string, CoursesCheckoutPreviewLine>
    isMutating?: boolean
    onRemove: (courseId: string) => void
    /** Combo-meter fill (0..3). */
    itemCount?: number
    /** Whether the current bundle tier is above zero ΓÇö gates the bonus chip. */
    bundlePercent?: number
    /** First load of the checkout preview, cart already settled ΓåÆ the footer summary shimmers. */
    isPreviewSkeleton?: boolean
    /** The real checkout preview ΓÇö total/savings/installments. `undefined` while pending or on error. */
    preview?: { totalChargedVnd: number; totalListVnd: number; savingsVnd: number }
    /** `true` ΓåÆ the preview fetch settled with an error; falls back to `fallbackTotalVnd`. */
    previewError?: boolean
    /** Sum of entity display prices ΓÇö shown only when the preview failed to load. */
    fallbackTotalVnd?: number
    /** Cheapest installment monthly amount, already formatted. `null` ΓåÆ no installment plans exist. */
    cheapestMonthlyLabel?: string | null
    onCheckout?: () => void
    onViewFullCart?: () => void
    labels: MiniCartDrawerLabels
}

/**
 * Mini-cart drawer ΓÇö the presentational half of {@link _MiniCartDrawer}'s connected
 * `MiniCartDrawer` (`index.tsx`): the slide-out cart confirmation + combo meter,
 * right on desktop / bottom-sheet on mobile. Composed on `DrawerShell` (the shared
 * panel-scaffold composite): a bordered `SurfaceListCard` reusing {@link CartLine}
 * (the SAME row the `/cart` page uses), a bundle-discount `ProgressMeter`, and a
 * footer with the real charged total + saving, a primary "Checkout" and a text
 * link to the full cart page. `error`/`isEmpty` fall to the shared
 * `AsyncContentError` / `AsyncContentEmpty` composites; otherwise the tree renders
 * with `isSkeleton` threaded down so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). See `tiers/split.md` ΓÇö the connected `index.tsx` owns
 * the fetch, the stores, and the i18n.
 *
 * @param props - {@link MiniCartDrawerProps}
 */
export const _MiniCartDrawer = ({
    isOpen,
    onOpenChange,
    isMobile,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBrowseCourses,
    items = [],
    previewByCourse,
    isMutating = false,
    onRemove,
    itemCount = 0,
    bundlePercent = 0,
    isPreviewSkeleton = false,
    preview,
    previewError = false,
    fallbackTotalVnd = 0,
    cheapestMonthlyLabel = null,
    onCheckout,
    onViewFullCart,
    labels,
}: MiniCartDrawerProps) => {
    const comboLabelRow = [
        () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={labels.comboLabel} />,
        ...(isSkeleton
            ? [() => <Chip isSkeleton tone="accent" />]
            : bundlePercent > 0
                ? [() => <Chip tone="accent" text={labels.bundleBonusChip} />]
                : []),
    ]
    const comboMeterItems = [
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                align="center"
                justify="between"
                items={comboLabelRow}
            />
        ),
        () => (isSkeleton ? <Skeleton.ProgressBar /> : <ProgressMeter value={itemCount} max={3} />),
        () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.comboHint} />,
    ]
    const comboMeterSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={3} items={comboMeterItems} />
    )

    // Line list ΓÇö reuses the SAME `CartLine` as the `/cart` page. `bordered`: this
    // list is NESTED inside the drawer surface, where `shadow-surface` renders
    // invisible against the parent (dark mode) ΓÇö nested cards need a border to
    // delineate (`card.md` ┬ºsurface-in-surface). The `/cart` PAGE keeps it
    // un-bordered (top-level on `bg-background`, shadow shows). `CartLine` has no
    // co-located skeleton of its own, so the loading rows are mirrored by hand,
    // same shape (leading tile ┬╖ two text lines ┬╖ trailing action).
    const cartLineSkeletonItems = [
        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                    () => <Skeleton className="h-4 w-24 rounded-lg" />,
                ]}
            />
        ),
        () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
    ]
    const cartListSection: ComponentTypeWithSkeleton = () => (
        <SurfaceListCard bordered>
            {isSkeleton
                ? Array.from({ length: 2 }).map((_row, index) => (
                    <StackH
                        key={index}
                        gap={1}
                        principle="card-padding"
                        explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome."
                        padding={5}
                        body={() => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center"
                                items={cartLineSkeletonItems}
                            />
                        )}
                    />
                ))
                : items.map((item) => (
                    <CartLine
                        key={item.id}
                        item={item}
                        previewLine={previewByCourse?.get(item.courseId)}
                        onRemove={onRemove}
                        isMutating={isMutating}
                    />
                ))}
        </SurfaceListCard>
    )

    // Body ΓÇö error ΓåÆ skeleton ΓåÆ empty ΓåÆ content (BLOCK-8): the empty and error
    // surfaces are the shared `AsyncContent*` composites dropped in as their own
    // states; otherwise the ONE tree renders, with `isSkeleton` threaded down so
    // the shimmer mirrors the loaded shape.
    const cartBody: ComponentTypeWithSkeleton = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return <StackV gap={6} isSkeleton={isSkeleton} items={[comboMeterSection, cartListSection]} />
    }

    const previewSkeletonTotalRow = [
        () => <Skeleton className="h-5 w-20 rounded-lg" />,
        () => <Skeleton className="h-7 w-32 rounded-lg" />,
    ]
    const totalPriceRow = [
        () => <Typography size="base" weight="semibold" text={labels.total} />,
        ...(preview
            ? [() => (
                <PriceTagInline
                    discounted={preview.totalChargedVnd}
                    original={preview.totalListVnd}
                    currency="VND"
                />
            )]
            // preview failed to load ΓÇö fall back to the plain list
            // total (no bundle discount known) so the total is never blank.
            : previewError
                ? [() => <PriceTagInline discounted={fallbackTotalVnd} currency="VND" />]
                : []),
    ]
    const totalSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={totalPriceRow}
            />
        ),
        ...(preview && preview.savingsVnd > 0
            ? [() => <Typography size="sm" color="success-soft" text={labels.savings} />]
            : []),
        ...(cheapestMonthlyLabel != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentHint} />]
            : []),
    ]
    const footerItems = [
        () => (
            isPreviewSkeleton ? (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center"
                    items={previewSkeletonTotalRow}
                />
            ) : (
                <StackV gap={2} items={totalSummaryItems} />
            )
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                isDisabled={isMutating}
                onPress={onCheckout}
                label={labels.checkout}
                classNames={["w-full"]}
            />
        ),
        () => (
            <Button
                variant="tertiary"
                onPress={onViewFullCart}
                label={labels.viewFullCart}
                classNames={["w-full"]}
            />
        ),
    ]
    const footerSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={4} items={footerItems} />
    )

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={labels.header}
            dialogClassName="sm:max-w-md"
            isSkeleton={isSkeleton}
            body={cartBody}
            footer={items.length > 0 ? footerSection : undefined}
            // HeroUI's `.drawer__footer` hard-codes `flex-row items-center justify-end
            // gap-2` (drawer.css) ΓÇö this footer needs a vertical stack (summary above
            // full-width buttons), so every conflicting axis is forced with the trailing
            // `!` important modifier, same technique `DrawerShell` itself uses for `mt-0!`.
            footerClassName="flex-col! items-stretch! justify-start! gap-3! border-t"
            identity={{ tier: "overlay", component: "MiniCartDrawer" }}
        />
    )
}

"use client"

import React, { useMemo } from "react"
import { useTranslations } from "next-intl"
import { useCvReviewLevelDetailsOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setSelectedCvReviewTemplateId } from "@/redux/slices/cv-review-level"
import { _CvReviewLevelDetailsModal, type CvReviewLevelOption } from "./component"

/**
 * CV review level modal ΓÇö the CONNECTED half: reads the overlay open-state
 * ({@link useCvReviewLevelDetailsOverlayState}) plus the rubric template rows
 * and the currently selected id (redux), resolves every label, and hands
 * everything to the presentational {@link _CvReviewLevelDetailsModal}.
 * Mounted prop-less by `ModalContainer`. See `tiers/split.md`.
 */
export const CvReviewLevelDetailsModal = () => {
    const { isOpen, setOpen } = useCvReviewLevelDetailsOverlayState()
    const dispatch = useAppDispatch()
    const selectedTemplateId = useAppSelector((state) => state.cvReviewLevel.selectedTemplateId)
    const templateCvsRows = useAppSelector((state) => state.templateCvs.rows)
    const t = useTranslations()

    const options = useMemo<Array<CvReviewLevelOption>>(
        () =>
            templateCvsRows.map((row) => ({
                id: row.id,
                title: row.title,
                description: row.description?.trim() || t("cv.submission.reviewLevelDetails.emptyDescription"),
            })),
        [
            templateCvsRows,
            t,
        ],
    )

    /** Select a rubric template, then close the modal. */
    const handleSelectReviewLevel = (templateId: string) => {
        dispatch(setSelectedCvReviewTemplateId(templateId))
        setOpen(false)
    }

    return (
        <_CvReviewLevelDetailsModal
            isOpen={isOpen}
            onOpenChange={setOpen}
            selectedTemplateId={selectedTemplateId}
            options={options}
            onSelect={handleSelectReviewLevel}
            labels={{
                selectionTitle: t("cv.submission.reviewLevelDetails.selectionTitle"),
                subtitle: t("cv.submission.reviewLevelDetails.subtitle"),
            }}
        />
    )
}

import React from "react"
import type { FollowListTab } from "@/hooks/zustand/overlay/store"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Tabs, type TabItem } from "@/components/atoms/navigation/Tabs"
import { Typography } from "@/components/atoms/text/Typography"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Box } from "@/components/frames/Box"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { StackH, StackV } from "@/components/frames/Stack"
import { InfiniteScrollSentinel } from "@/components/blocks/async/InfiniteScrollSentinel"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/**
 * `_FollowListModal` ΓÇö the presentational half of {@link FollowListModal}
 * (`index.tsx`): the followers / following lists for one profile, each an
 * infinite-scroll roster of clickable users. Composes `ModalShell` + `Tabs`
 * (a count beside each label) + `SurfaceCardList` (free-form rows reusing the
 * `UserCell` composite) inside a bounded scroll region. Error/empty fall to
 * the shared `AsyncContentError`/`AsyncContentEmpty` frames, dropped into
 * `SurfaceCardList`'s own `errorState`/`emptyState` slots (`isEmpty` is
 * derived by that list from `items.length`, never passed in separately);
 * otherwise the tree renders with `isSkeleton` threaded into each
 * placeholder row's `UserCell`. See `tiers/split.md` ΓÇö the connected
 * `index.tsx` (unchanged public name `FollowListModal`) owns the overlay
 * store, the two `useSWRInfinite` hooks (only the active tab fetches), and
 * every translated string.
 */

/** The two follow-graph directions, in tab order. */
const TABS: ReadonlyArray<FollowListTab> = ["followers", "following"]

/** How many placeholder rows mirror the list while the first page hasn't landed yet. */
const FOLLOW_LIST_SKELETON_ROW_COUNT = 5

/** One row of either list, already resolved by the connected `FollowListModal` ΓÇö no raw entity. */
export interface FollowListRow {
    /** Opaque id ΓÇö the row's `key`; also resolves the profile route on click. */
    globalId: string
    username: string
    /** Falls back to {@link FollowListRow.username} at the connected layer when unset. */
    displayName: string
    avatar?: string | null
    /** `@username`, already built by the connected layer. */
    handle: string
}

/** All display text, already localized by the connected `FollowListModal`; a story passes i18n keys. */
export interface FollowListModalLabels {
    title: string
    followersTab: string
    followingTab: string
    /** `t("followList.empty.<tab>")` for the CURRENTLY active tab, already picked. */
    empty: string
    errorTitle: string
    errorRetry: string
}

/** Props for {@link _FollowListModal} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface FollowListModalProps {
    /** Whether the modal is currently open. Forwarded to {@link ModalShell}. */
    isOpen: boolean
    /** Open-state change handler. Forwarded to {@link ModalShell}. */
    onOpenChange: (open: boolean) => void
    /** Active direction (controlled ΓÇö the connected half gates which `useSWRInfinite` hook fetches). */
    tab: FollowListTab
    onTabChange: (tab: FollowListTab) => void
    /** Follower / following counts, shown beside each tab's label. */
    counts: Record<FollowListTab, number>
    /** The active tab's rows (nearest page first), already resolved. Empty while {@link isSkeleton} is on. */
    rows: Array<FollowListRow>
    /** Go to a user's profile ΓÇö the connected half also closes the modal in the same handler. */
    onOpenUser: (username: string) => void
    /** `true` ΓåÆ the sentinel below the list can still grow it. */
    hasMore: boolean
    /** Grow the active list by one page. */
    onLoadMore: () => void
    /** A page is already in flight ΓÇö the sentinel stays detached meanwhile. */
    isLoadingMore?: boolean
    /** First load of the active tab, nothing in hand yet ΓåÆ the list mirrors itself. */
    isSkeleton?: boolean
    /** Truthy ΓåÆ the list falls to its error message (beats the skeleton, per `SurfaceCardList`). */
    error?: unknown
    onRetry: () => void
    labels: FollowListModalLabels
}

/**
 * The follow-list modal. See the file header for the full contract.
 *
 * @param props - {@link FollowListModalProps}
 */
export const _FollowListModal = ({
    isOpen,
    onOpenChange,
    tab,
    onTabChange,
    counts,
    rows,
    onOpenUser,
    hasMore,
    onLoadMore,
    isLoadingMore = false,
    isSkeleton = false,
    error,
    onRetry,
    labels,
}: FollowListModalProps) => {
    const tabLabel: Record<FollowListTab, string> = {
        followers: labels.followersTab,
        following: labels.followingTab,
    }

    // A count beside a tab label is not `TabItem.badge` (that anchors a
    // notification-style chip OVER the label, `color="danger"` ΓÇö the wrong
    // voice for a plain quantity). No block owns "label + muted count" either,
    // so this stays minimal, inline composition of existing atoms/frames.
    const tabItems: Array<TabItem> = TABS.map((tabId) => ({
        key: tabId,
        label: (
            <StackH
                gap={3}
                principle="value-row"
                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                align="center"
                items={[
                    () => <>{tabLabel[tabId]}</>,
                    () => <Typography size="sm" color="muted" tabularNums text={String(counts[tabId])} />,
                ]}
            />
        ),
    }))

    const skeletonRows: Array<SurfaceCardListItem> = Array.from(
        { length: FOLLOW_LIST_SKELETON_ROW_COUNT },
        (_row, index) => ({
            key: `skeleton-${index}`,
            content: () => <UserCell username="" handle="@" isSkeleton />,
        }),
    )

    const followRows: Array<SurfaceCardListItem> = rows.map((row) => ({
        key: row.globalId,
        content: () => (
            <UserCell
                username={row.username}
                displayName={row.displayName}
                avatar={row.avatar}
                handle={row.handle}
            />
        ),
        onPress: () => onOpenUser(row.username),
    }))

    const listBody: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={2}
            items={[
                () => (
                    <SurfaceCardList
                        items={isSkeleton ? skeletonRows : followRows}
                        isSkeleton={isSkeleton}
                        error={error}
                        errorState={() => (
                            <AsyncContentError
                                title={labels.errorTitle}
                                onRetry={onRetry}
                                retryLabel={labels.errorRetry}
                            />
                        )}
                        emptyState={() => <AsyncContentEmpty title={labels.empty} />}
                    />
                ),
                // grow the list as the sentinel scrolls into view ΓÇö only while the
                // content branch is actually on screen (the error/skeleton/empty
                // branches above have nothing below them worth loading more of).
                ...(!isSkeleton && !error && rows.length > 0
                    ? [() => (
                        <InfiniteScrollSentinel
                            onReach={onLoadMore}
                            disabled={!hasMore || isLoadingMore}
                        />
                    )]
                    : []),
            ]}
        />
    )

    // Tabs Γåö list-below = 2 different-function zones (nav vs content) ΓåÆ gap-6,
    // not gap-3 (fe/foundations/gap.md's between-block rule).
    const modalBody: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={6}
            items={[
                () => (
                    <Tabs
                        items={tabItems}
                        selectedKey={tab}
                        onSelectionChange={(key) => onTabChange(key as FollowListTab)}
                        ariaLabel={labels.title}
                        variant="secondary"
                    />
                ),
                // NEW-VOCABULARY GAP: no frame owns "cap this region's height and
                // scroll it locally" outside a page shell ΓÇö `ScrollArea`'s
                // `classNames` is a closed, positioning-only enum (no height
                // values), and `PinnedTrack` hard-owns the page-shell's own
                // `sticky top-0 z-40` for its one real consumer. `ScrollArea`
                // still owns the `overflow-y-auto` behaviour; only the height
                // cap itself has nowhere to live yet, so it goes through `Box`
                // (the sanctioned raw-appearance escape hatch) rather than a
                // bare `div`.
                () => (
                    <Box className="max-h-[60vh]">
                        <ScrollArea axis="y" body={listBody} />
                    </Box>
                ),
            ]}
        />
    )

    return (
        <ModalShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            size="sm"
            title={labels.title}
            body={modalBody}
            identity={{ tier: "overlay", component: "FollowListModal" }}
        />
    )
}

import React from "react"
import { Calendar } from "@heroui/react"
import { CalendarDate, getLocalTimeZone, today, type DateValue } from "@internationalized/date"
import { ClockIcon } from "@phosphor-icons/react"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Box } from "@/components/frames/Box"

/** One recurring livestream session, fully resolved for display by the connected `LivestreamCalendarModal`. */
export interface LivestreamCalendarSessionRow {
    /** Stable row key (the session id). */
    id: string
    /** Weekday label, already localized (`t("livestream.calendar.days.<dow>")`). */
    dayLabel: string
    /** `"09:00 - 10:00"`-shaped range, already localized + interpolated. */
    timeRangeLabel: string
    /** "Next on <date>" line, already localized + interpolated with the formatted date. */
    nextOnLabel: string
    /** Session note, raw markdown source ΓÇö `undefined` when blank/absent. */
    note?: string
}

/** All display text, already localized by the connected `LivestreamCalendarModal`; a story passes i18n keys. */
export interface LivestreamCalendarModalLabels {
    /** Modal header title. */
    modalTitle: string
    /** Accessible name for the calendar grid. */
    calendarAriaLabel: string
    /** Empty-state title, shown when there are no recurring sessions. */
    emptyTitle: string
}

/** Props for {@link _LivestreamCalendarModal} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface LivestreamCalendarModalProps {
    /** Whether the modal is currently open. */
    isOpen: boolean
    /** Open-state change handler ΓÇö backdrop click, Escape, close button. */
    onOpenChange: (open: boolean) => void
    /** Date the calendar opens focused on ΓÇö the next occurrence of the earliest session, or `undefined` when there are none. */
    defaultFocusedValue?: CalendarDate
    /** `true` for a weekday the course has no recurring session on ΓÇö dims it in the grid. */
    isDateUnavailable: (date: DateValue) => boolean
    /** The recurring sessions, already sorted for display (latest weekday first). */
    rows: Array<LivestreamCalendarSessionRow>
    labels: LivestreamCalendarModalLabels
}

/** One row's free-form body: day/time chip row, the next-occurrence line, and an optional note. */
const sessionRowContent = (row: LivestreamCalendarSessionRow) => (
    <StackV
        gap={4}
        items={[
            () => (
                <Cluster
                    gap={3}
                    align="center"
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    items={[
                        () => <Chip text={row.dayLabel} />,
                        () => <ClockIcon aria-hidden focusable="false" className="size-3 text-muted" />,
                        () => <Typography size="sm" color="muted" text={row.timeRangeLabel} />,
                    ]}
                />
            ),
            () => <Typography size="sm" text={row.nextOnLabel} />,
            ...(row.note ? [() => <MarkdownContent source={row.note as string} measure="compact" />] : []),
        ]}
    />
)

/**
 * `_LivestreamCalendarModal` ΓÇö the presentational half of `LivestreamCalendarModal`:
 * a date-picker calendar (dims any weekday with no recurring session) above a bounded
 * list of the course's recurring livestream sessions (day + time-range chip row, next
 * occurrence, an optional markdown note). Composes `ModalShell` (dialog scaffold) +
 * `SurfaceCardList` (the row list) + `MarkdownContent` (the note); falls to
 * `AsyncContentEmpty` when there are no sessions to show.
 *
 * ΓÜá∩╕Å MISSING VOCABULARY: there is no atom/composite wrapping a STANDALONE, always-visible
 * HeroUI `Calendar` (`atoms/forms/Input`'s `InputDate` only wraps one inside a text-field
 * popover). Kept as a direct `@heroui/react` import here, minimal, pending that atom ΓÇö
 * see the task's `missingVocabulary` report. Do not spread this pattern elsewhere. The
 * `DateValue` type it needs comes from `@internationalized/date` (the same nominal type
 * `@heroui/react/rac` re-exports) so this stays the ONLY direct HeroUI import in the file;
 * `Box` (the frames escape hatch for "a composite wrapping a foreign library") carries the
 * `overflow-hidden`/`shadow-none` reset instead of a raw `className` on `Calendar` itself.
 *
 * No `isSkeleton`: `rows` comes straight off redux (`state.livestreamSession.entities`,
 * populated synchronously wherever the store is hydrated), so there is no async
 * first-load formula to compute a skeleton from ΓÇö the original component had no
 * loading state either.
 *
 * @param props - {@link LivestreamCalendarModalProps}
 */
export const _LivestreamCalendarModal = ({
    isOpen,
    onOpenChange,
    defaultFocusedValue,
    isDateUnavailable,
    rows,
    labels,
}: LivestreamCalendarModalProps) => {
    const isEmpty = rows.length === 0

    const calendarSlot = () => (
        <Box className="overflow-hidden shadow-none">
            <Calendar
                aria-label={labels.calendarAriaLabel}
                defaultFocusedValue={defaultFocusedValue}
                defaultValue={today(getLocalTimeZone())}
                firstDayOfWeek="mon"
                isDateUnavailable={isDateUnavailable}
            />
        </Box>
    )

    const listItems: Array<SurfaceCardListItem> = rows.map((row) => ({
        key: row.id,
        content: () => sessionRowContent(row),
    }))

    const bodyItems = [
        // Center via Box ΓÇö no sibling gap seam; StackV gap={1} align=center was inert.
        () => <Box className="flex justify-center">{calendarSlot()}</Box>,
        () => <SurfaceCardList items={listItems} variant="nested" />,
    ]

    const bodySlot = () => (
        isEmpty ? (
            <AsyncContentEmpty title={labels.emptyTitle} />
        ) : (
            <StackV gap={4} items={bodyItems} />
        )
    )

    return (
        <ModalShell
            identity={{ tier: "overlay", component: "LivestreamCalendarModal" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={labels.modalTitle}
            size="lg"
            containerClassName="max-w-lg"
            body={bodySlot}
        />
    )
}

import { type SelectOption, SelectSingle } from "@/components/atoms/forms"
import React from "react"
import { ArrowRightIcon, GraduationCapIcon, LockIcon } from "@phosphor-icons/react"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Toolbar } from "@/components/composites/navigation/Toolbar"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { PriceTagProminent, PriceTagInline, type PriceCurrency } from "@/components/blocks/commerce/PriceTag"
import { IconTile } from "@/components/atoms/display/IconTile"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Spinner } from "@/components/atoms/display/Spinner"

import { StackV, StackH } from "@/components/frames/Stack"
import { PaymentType } from "@/modules/types/enums/payment-type"

/**
 * `_PaymentModal` ΓÇö the SRC TWIN of the shared payment overlay: order summary
 * ("Summary" panel) then gateway pick ("Payment" panel), for every paid flow
 * (course enroll ┬╖ multi-course checkout ┬╖ membership ┬╖ AI subscription).
 * Presentational: typed props, already resolved; no fetch/store/i18n (that's
 * the connected half, `./index.tsx`).
 *
 * Only the price region skeletons (`isSkeleton` flows into the order's
 * `PriceTagInline`/`PriceTagProminent` leaves only) ΓÇö the tabs, installment
 * picker, voucher field and gateway list render immediately, mirroring
 * `PremiumGateModal`'s own "only the price region rests" contract.
 */

/** Which of the modal's two panels is showing ΓÇö freely switchable, not a wizard. */
export type PaymentModalTab = "summary" | "payment"

/** One course row of the multi-course cart summary. */
export interface PaymentModalCheckoutLine {
    /** Stable row key (the course id). */
    key: string
    /** Course title. */
    title: string
    /** Course cover image, when known. */
    coverUrl?: string | null
    /** Real charged price in the active currency; `undefined` while its preview hasn't resolved. */
    discounted?: number | null
    /** List price in the active currency, struck through when it beats {@link PaymentModalCheckoutLine.discounted}. */
    original?: number | null
}

/** One loyalty-breakdown row ΓÇö WHY the discount applies (course flow only). */
export interface PaymentModalLoyaltyRow {
    /** Stable row key. */
    key: string
    /** Leading icon, a COMPONENT reference ΓÇö never already-built JSX. */
    icon: TypographyIcon
    /** Already-translated reason line. */
    label: string
}

/** One gateway inside {@link PaymentModalGatewayGroup}. */
export interface PaymentModalGatewayMethod {
    /** The gateway. */
    type: PaymentType
    /** Gateway display name (e.g. "PayOS"). */
    name: string
    /** Already-translated one-line description. */
    description: string
    /** Gateway logo. */
    iconUrl: string
    /** Amount charged through this gateway, already formatted; omitted while the price hasn't resolved. */
    amountLabel?: string
    /** `true` while a checkout through THIS gateway is in flight ΓÇö swaps the row's trailing arrow for a spinner. */
    isPending: boolean
}

/** The gateway group for the active currency (domestic VND Γåö international USD). */
export interface PaymentModalGatewayGroup {
    /** Group label (e.g. "Domestic"). */
    label: string
    /** Currency tag shown beside the label (e.g. "VND"). */
    currencyLabel: string
    /** Gateways in this group, in display order. */
    methods: ReadonlyArray<PaymentModalGatewayMethod>
}

/** All display text, already localized by the connected `PaymentModal`; a story passes i18n keys. */
export interface PaymentModalLabels {
    title: string
    tabsAria: string
    tabSummary: string
    tabPayment: string
    continueToPayment: string
    total: string
    priceError: string
    membershipPrice: string
    installmentTitle: string
    payFull: string
    payInstallment: string
    /** "3 months" ΓÇö set only once a term is chosen. */
    installmentMonths?: string
    /** "ΓÇª/month" ΓÇö set only once a term is chosen. */
    installmentPerMonth?: string
    /** Total + markup summary line ΓÇö set only once a term is chosen. */
    installmentSummary?: string
    voucherTitle: string
    voucherNone: string
    voucherVndOnlyHint: string
    currencyVnd: string
    currencyUsd: string
    secure: string
    noCardStored: string
}

/** Props for {@link _PaymentModal} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface PaymentModalProps {
    /** Whether the modal is currently open. */
    isOpen: boolean
    /** Open/close callback. */
    onOpenChange: (open: boolean) => void

    /** Which panel is showing. */
    selectedTab: PaymentModalTab
    /** Fired when the learner switches panels (via the tab strip, or the "Continue" CTA). */
    onSelectedTabChange: (tab: PaymentModalTab) => void

    /** Product name (course title / cart count / AI tier / membership). */
    orderName: string
    /** Course cover for the single-item summary icon tile; omitted for every other flow. */
    orderCoverUrl?: string | null
    /** Multi-course cart lines; omitted for every single-product flow. */
    checkoutLines?: ReadonlyArray<PaymentModalCheckoutLine>

    /** The charged price (single-item summary, or the cart's charged total) in the active currency. */
    discounted?: number | null
    /** The list price, struck through when it beats {@link PaymentModalProps.discounted}. */
    original?: number | null
    /** Active-phase price before loyalty ΓÇö feeds the breakdown popover's middle step (course flow only). */
    phase?: number | null
    /** Loyalty discount percent (0 = no loyalty row). */
    discountPercent: number
    /** `true` ΓåÆ no numeric price exists yet; shows the flat membership heading instead of a `PriceTag`. */
    isMembershipFlow: boolean
    /** Loyalty breakdown rows (course flow only); empty elsewhere. */
    loyaltyRows: ReadonlyArray<PaymentModalLoyaltyRow>

    /** Currency the summary price + gateway list are shown in. */
    currency: PriceCurrency
    /**
     * `true` ΓåÆ the price region rests: only the `PriceTagInline`/`PriceTagProminent`
     * leaves shimmer, the rest of the panel (tabs, installment, voucher, gateways)
     * renders immediately.
     */
    isSkeleton?: boolean
    /** `true` ΓåÆ the price region failed to load; replaces it with an error message. */
    priceError?: boolean

    /** `true` ΓåÆ the "pay in full / pay in installments" picker shows (course flows with terms offered). */
    installmentAvailable: boolean
    /** `true` ΓåÆ an installment term is the active plan (clamps the order to VND). */
    installmentActive: boolean
    /** Fired when the learner toggles between "pay in full" and "pay in installments". */
    onInstallmentActiveChange: (active: boolean) => void

    /** `true` ΓåÆ the apply-voucher field shows (course flow, with applicable vouchers). */
    showVoucher: boolean
    /** Options for the apply-voucher field ΓÇö a leading "no voucher" row plus one per applicable voucher. */
    voucherOptions: Array<SelectOption>
    /** Applied voucher code, `null` = none. */
    voucherCode: string | null
    /** Fired when the learner picks a voucher (or clears it). */
    onVoucherCodeChange: (code: string | null) => void
    /** `true` ΓåÆ the applied voucher is VND-only (clamps the order to the domestic side). */
    flatVoucherActive: boolean

    /** `true` ΓåÆ international (USD) gateways are usable for this order ΓÇö the currency toggle shows. */
    hasUsd: boolean
    /** Fired when the learner switches the domestic/international currency. */
    onCurrencyChange: (currency: PriceCurrency) => void

    /** Gateways for the active currency; omitted only while no flow context is open. */
    activeGroup?: PaymentModalGatewayGroup
    /** Fired when the learner picks a gateway row. */
    onSelectMethod: (type: PaymentType) => void
    /** `true` while any checkout mutation is in flight ΓÇö disables every gateway row. */
    isMutating: boolean

    labels: PaymentModalLabels
}

/**
 * One course row of the multi-course cart summary ΓÇö icon tile, truncated title, and
 * (once resolved) its real charged price.
 */
const checkoutLineRow = (
    line: PaymentModalCheckoutLine,
    currency: PriceCurrency,
    isSkeleton: boolean,
) => (
    <StackH
        gap={4}
        principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        align="center"
        items={[
            () => (
                <IconTile
                    size="sm"
                    tone="accent"
                    icon={GraduationCapIcon}
                    src={line.coverUrl}
                    alt={line.title}
                />
            ),
            () => (
                <Typography
                    size="sm"
                    truncate
                    classNames={["min-w-0", "flex-1"]}
                    text={line.title}
                />
            ),
            ...(isSkeleton || line.discounted != null
                ? [() => (
                    <PriceTagInline
                        discounted={line.discounted ?? 0}
                        original={line.original}
                        currency={currency}
                        isSkeleton={isSkeleton}
                        showSavingLine={false}
                        classNames={["shrink-0"]}
                    />
                )]
                : []),
        ]}
    />
)

/** The order summary panel ΓÇö a multi-course cart list + total, or a single-item price + loyalty breakdown. */
const summaryContent = (props: PaymentModalProps) => {
    const {
        orderName,
        orderCoverUrl,
        checkoutLines,
        discounted,
        original,
        phase,
        discountPercent,
        isMembershipFlow,
        loyaltyRows,
        currency,
        isSkeleton = false,
        priceError = false,
        labels,
        onSelectedTabChange,
    } = props

    if (priceError) {
        return <AsyncContentError title={labels.priceError} />
    }

    if (checkoutLines != null) {
        const checkoutLineItems = checkoutLines.map((line) => () => checkoutLineRow(line, currency, isSkeleton))
        const totalRow = [
            () => <Typography size="sm" weight="semibold" text={labels.total} />,
            ...(isSkeleton || discounted != null
                ? [() => (
                    <PriceTagProminent
                        discounted={discounted ?? 0}
                        original={original}
                        currency={currency}
                        isSkeleton={isSkeleton}
                        showSavingLine={false}
                        classNames={["shrink-0"]}
                    />
                )]
                : []),
        ]
        const checkoutSummaryItems = [
            () => <StackV gap={4} items={checkoutLineItems} />,
            () => (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    justify="between"
                    items={totalRow}
                />
            ),
        ]
        return (
            <StackV
                gap={5}
                principle="group-boundary"
                explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                divider
                items={checkoutSummaryItems}
            />
        )
    }

    const priceRegion = isSkeleton || discounted != null
        ? (
            <PriceTagProminent
                discounted={discounted ?? 0}
                original={original}
                currency={currency}
                isSkeleton={isSkeleton}
                breakdown={phase != null ? { phase, loyaltyPercent: discountPercent } : undefined}
            />
        )
        : isMembershipFlow
            ? <Typography size="h4" weight="bold" text={labels.membershipPrice} />
            : null

    const orderIdentityItems = [
        () => (
            <IconTile
                size="sm"
                tone="accent"
                icon={GraduationCapIcon}
                src={orderCoverUrl}
                alt={orderName}
            />
        ),
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Typography size="xs" color="muted" truncate text={orderName} />,
                    () => priceRegion,
                ]}
            />
        ),
    ]

    const singleSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={orderIdentityItems}
            />
        ),
        ...(loyaltyRows.length > 0
            ? [() => (
                <StackV
                    gap={3}
                    items={loyaltyRows.map((row) => () => (
                        <InlineIconLabel icon={row.icon} label={row.label} tone="success" size="xs" />
                    ))}
                />
            )]
            : []),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                iconSlide
                classNames={["w-full"]}
                label={labels.continueToPayment}
                onPress={() => onSelectedTabChange("payment")}
            />
        ),
    ]

    return <StackV gap={4} items={singleSummaryItems} />
}

/** One gateway row ΓÇö leading logo, name + description, amount, and a trailing arrow/spinner. */
const gatewayRow = (
    method: PaymentModalGatewayMethod,
    onSelectMethod: (type: PaymentType) => void,
    isMutating: boolean,
): SurfaceCardListItem => ({
    key: method.type,
    leading: () => (
        <img
            alt={method.name}
            className="h-8 w-12 shrink-0 object-contain object-left"
            src={method.iconUrl}
        />
    ),
    title: method.name,
    subtitle: method.description,
    metaText: method.amountLabel,
    trailing: () => (
        method.isPending
            ? <Spinner size="sm" />
            : <ArrowRightIcon aria-hidden focusable="false" className="size-5 text-muted" />
    ),
    onPress: () => onSelectMethod(method.type),
    isDisabled: isMutating,
})

/** The payment panel ΓÇö installment picker, apply-voucher, currency toggle, gateway list, trust line. */
const paymentContent = (props: PaymentModalProps) => {
    const {
        installmentAvailable,
        installmentActive,
        onInstallmentActiveChange,
        showVoucher,
        voucherOptions,
        voucherCode,
        onVoucherCodeChange,
        flatVoucherActive,
        hasUsd,
        currency,
        onCurrencyChange,
        activeGroup,
        onSelectMethod,
        isMutating,
        labels,
    } = props

    const installmentMonthsRow = [
        () => <Typography size="sm" weight="semibold" text={labels.installmentMonths ?? ""} />,
        () => <Typography size="sm" color="muted" text={labels.installmentPerMonth ?? ""} />,
    ]

    const installmentSectionItems = [
        () => <Typography size="xs" weight="medium" color="muted" text={labels.installmentTitle} />,
        () => (
            <Toolbar
                variant="primary"
                size="sm"
                leftTabs={{
                    selectedKey: installmentActive ? "installment" : "full",
                    ariaLabel: labels.installmentTitle,
                    onSelectionChange: (key) => onInstallmentActiveChange(String(key) === "installment"),
                    items: [
                        { key: "full", label: labels.payFull },
                        { key: "installment", label: labels.payInstallment },
                    ],
                }}
            />
        ),
        ...(installmentActive && labels.installmentMonths != null
            ? [() => (
                <SurfaceCard
                    variant="nested"
                    padding={4}
                    body={() => (
                        <StackH
                            gap={4}
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            justify="between"
                            items={installmentMonthsRow}
                        />
                    )}
                />
            )]
            : []),
        ...(labels.installmentSummary != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentSummary ?? ""} />]
            : []),
    ]

    const voucherSectionItems = [
        () => (
            <SelectSingle
                label={labels.voucherTitle}
                ariaLabel={labels.voucherTitle}
                placeholder={labels.voucherNone}
                options={voucherOptions}
                value={voucherCode ?? ""}
                onValueChange={(value) => onVoucherCodeChange(value || null)}
                isDisabled={isMutating}
            />
        ),
        ...(flatVoucherActive
            ? [() => <Typography size="xs" color="muted" text={labels.voucherVndOnlyHint} />]
            : []),
    ]

    const trustLineItems = [
        () => <InlineIconLabel icon={LockIcon} label={labels.secure} size="xs" />,
        () => <Typography size="xs" color="muted" text={labels.noCardStored} />,
    ]

    const paymentPanelItems = [
        ...(installmentAvailable
            ? [() => <StackV gap={4} items={installmentSectionItems} />]
            : []),
        ...(showVoucher
            ? [() => <StackV gap={4} items={voucherSectionItems} />]
            : []),
        ...(hasUsd
            ? [() => (
                <Toolbar
                    variant="primary"
                    leftTabs={{
                        selectedKey: currency,
                        ariaLabel: labels.title,
                        onSelectionChange: (key) => onCurrencyChange(String(key) as PriceCurrency),
                        items: [
                            { key: "VND", label: labels.currencyVnd },
                            { key: "USD", label: labels.currencyUsd },
                        ],
                    }}
                />
            )]
            : []),
        ...(activeGroup
            ? [() => (
                <SurfaceCardList
                    label={activeGroup.label}
                    labelEnd={activeGroup.currencyLabel}
                    items={activeGroup.methods.map((method) => gatewayRow(method, onSelectMethod, isMutating))}
                />
            )]
            : []),
        () => (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                items={trustLineItems}
            />
        ),
    ]

    return <StackV gap={4} items={paymentPanelItems} />
}

/**
 * Shared payment modal for every paid flow. See the file header for the panel
 * layout and the `isSkeleton` contract.
 *
 * @param props - {@link PaymentModalProps}
 */
const _PaymentModal = (props: PaymentModalProps) => {
    const { isOpen, onOpenChange, selectedTab, onSelectedTabChange, labels } = props

    const body = () => (
        <StackV
            gap={6}
            items={[
                () => (
                    <Toolbar
                        leftTabs={{
                            selectedKey: selectedTab,
                            ariaLabel: labels.tabsAria,
                            onSelectionChange: (key) => onSelectedTabChange(String(key) as PaymentModalTab),
                            items: [
                                { key: "summary", label: labels.tabSummary },
                                { key: "payment", label: labels.tabPayment },
                            ],
                        }}
                    />
                ),
                () => (selectedTab === "summary" ? summaryContent(props) : paymentContent(props)),
            ]}
        />
    )

    return (
        <ModalShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={labels.title}
            size="sm"
            body={body}
            identity={{ tier: "overlay", component: "PaymentModal" }}
        />
    )
}

export { _PaymentModal }

"use client"

import React, { useEffect, useMemo, useState } from "react"
import { toast } from "@/modules/toast/toast"
import useSWR from "swr"
import { CombinedGraphQLErrors } from "@apollo/client"
import { FlameIcon, GraduationCapIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { useMutateCourseEnrollSwr } from "@/hooks/swr/api/graphql/mutations/useMutateCourseEnrollSwr"
import { useMutateCoursesCheckoutSwr } from "@/hooks/swr/api/graphql/mutations/useMutateCoursesCheckoutSwr"
import { useMutatePurchaseAiSubscriptionSwr } from "@/hooks/swr/api/graphql/mutations/useMutatePurchaseAiSubscriptionSwr"
